"""Eighty original 2027 shared-level approach questions; no bank imports.

All scenarios and schematic stimulus material are constructed for practice.
Worked answers are indicative arguments assessed by holistic best-fit bands.
"""
import json, re, math, textwrap
from pathlib import Path
from common import question, write_collection, evidence, dump, svg, text, line, rect, DOCS, ROOT

GUIDE='https://ibo.org/globalassets/new-structure/university-admission/pdfs/subject-guides/psychology-first-assessment-2027-guide-sbs.pdf'
SOURCES={
 'imaging':'https://www.nature.com/articles/35084005',
 'plasticity':'https://pmc.ncbi.nlm.nih.gov/articles/PMC18253/',
 'inheritance':'https://pubmed.ncbi.nlm.nih.gov/25985137/',
 'anchoring':'https://pubmed.ncbi.nlm.nih.gov/17835457/',
 'load':'https://onlinelibrary.wiley.com/doi/10.1207/s15516709cog1202_4',
 'confirmation':'https://journals.sagepub.com/doi/10.1080/17470216008416717'
}
B=[];C=[];ledger=[];figures={}

def card_figure(title, cards, note='Constructed scenario schematic; no research results shown.'):
    """Neutral stimulus cards: coordinates and meanings retained for review."""
    count=len(cards)
    assert count in (2,3,4)
    width=360;cardw=330;cardh=80;height=80+count*95
    titlelines=textwrap.wrap(title,34);body='';coords=[]
    for j,label in enumerate(titlelines):body+=text(180,24+j*21,label,18,'middle')
    top=38 if len(titlelines)==1 else 58
    for i,(head,detail) in enumerate(cards):
        x=15;y=top+i*95
        body+=rect(x,y,cardw,cardh)+text(180,y+25,head,16,'middle')
        lines=textwrap.wrap(detail,40)
        assert len(lines)<=2,(head,detail)
        for j,s in enumerate(lines):body+=text(180,y+48+18*j,s,14,'middle')
        coords.append(dict(x=x,y=y,width=cardw,height=cardh,heading=head,detail=detail))
    height=max(height,top+count*95+22)
    body+=text(180,height-12,'Constructed conceptual stimulus, not research data.',11,'middle')
    figure=svg(body,width,height,title)
    return figure,dict(type='conceptual cards',viewBox=[0,0,width,height],cards=coords,caption=note,meaning='Cards contain only the givens, not the evaluated explanation. No quantitative outcome is encoded; reading order is top-to-bottom. The 360-unit viewBox and 14–18-unit main text retain approximately 12–16 px labels at 314 px width.')

def add(token,n,title,code,section,context,concepts,stem,steps,*,fig=None,sources=None,difficulty=None,alternative=None):
    difficulty=difficulty or ('medium' if n<=16 or n in (25,29,33,37) else 'hard')
    if section=='p1-c':
        names=', '.join(concepts[:-1])+' and '+concepts[-1]
        stem+=' In your response, consider the concepts of '+names+'.'
    figure,geometry=fig if fig else (None,None)
    q=question(token,n,title,code,section,stem,steps,difficulty=difficulty,context=context,concepts=concepts,summary=steps[-1],diagram=figure,caption=geometry['caption'] if geometry else None)
    words=len(re.findall(r"\b[\w'-]+\b",' '.join(steps)))
    minimum={4:70,6:100,15:220}[q['marks']]
    assert words>=minimum,(q['id'],words,minimum)
    q['verification']['notes']=f"Author checked the specific mechanism, conceptual demand and alternatives: {steps[0]}"
    record=evidence(q,steps[0]+' '+steps[-1],sources=[GUIDE]+(sources or []),figure=geometry,alternatives=alternative or [steps[-1]])
    record.update(workedAnswerWords=words,examSection=section,context=context,concepts=concepts,authorChecks={'holisticBandsNotAdditive':True,'selfContainedPrompt':True,'noInventedPublishedFindings':True,'noDirectSlStatisticalAnalysis':True,'sourceMechanismScope':'Framework/measurement sources only; all new scenario details are fictional and are not claimed as published results.'})
    (B if token=='bio' else C).append(q);ledger.append(record)
    if geometry:figures[q['id']]=geometry
    return q

# Biological content knowledge: eight context-free, example-based questions.
add('bio',1,'What an animal model represents','BIO.01','p1-a','general',['perspective','responsibility'],
 'Explain how an animal model can contribute to understanding one human behaviour, using one example.',[
 'An animal model represents selected processes relevant to a human behaviour rather than reproducing a complete human experience. For example, a researcher might use a rodent navigation task to investigate neural processes involved in spatial learning. Controlled conditions can help isolate a proposed mechanism that is difficult to examine directly in humans.',
 'The explanatory link is the potentially shared learning or neural process, not a claim that navigating a maze is identical to navigating a human city. Differences in language, experience and social context restrict translation. An accurate example should connect what is modelled to the particular human behaviour and acknowledge why the comparison is useful.'])
add('bio',2,'Explaining at one level','BIO.02','p1-a','general',['perspective','causality'],
 'Explain biological reductionism with reference to one example of human behaviour.',[
 'Biological reductionism explains a complex behaviour primarily through lower-level biological components, such as neural signalling or inherited variation. For example, an account of anxiety might focus on the activity of threat-processing circuits. This can make a proposed mechanism specific enough to investigate, rather than treating anxiety as a single unexplained label.',
 'It becomes reductionist when that level is treated as sufficient despite the possible influence of interpretation, learning and social conditions. The same bodily arousal could accompany different experiences in different settings. Thus the example illustrates both the biological explanatory level and the information that may be lost when a complex behaviour is reduced to it.'])
add('bio',3,'A functional imaging example','BIO.03','p1-a','general',['measurement','perspective'],
 'Explain how one brain imaging technique can help psychologists understand a human behaviour, using one example.',[
 'Functional magnetic resonance imaging can compare blood-oxygenation-related signals while a person performs different tasks. For example, contrasting a navigation task with an appropriate control task can help identify a network associated with spatial processing. The technique allows brain function to be investigated without deliberately damaging the brain.',
 'The signal is an indirect physiological measure, not a picture of thoughts or a direct count of neuronal firing. Task differences and other influences need consideration before attributing the contrast to one process. A good explanation connects the particular measurement to the behavioural example without claiming that activation alone establishes that a region causes the behaviour.'],sources=[SOURCES['imaging']])
add('bio',4,'Messages with behavioural effects','BIO.04','p1-a','general',['causality','perspective'],
 'Explain the role of one chemical messenger in one human behaviour, using an example.',[
 'A chemical messenger influences activity by interacting with appropriate receptors, changing the likelihood of responses in a relevant biological system. Cortisol, for example, is a hormone involved in the response to a perceived challenge. In an illustrative stressful situation it can contribute to physiological adjustments that accompany alertness and coping.',
 'Its role is a contribution to a coordinated response, not a complete explanation of what a person decides to do. Appraisal, prior experience, timing and receptor effects also matter. The example should connect the messenger’s biological action to a clearly identified behaviour while avoiding the claim that one chemical inevitably produces the same behaviour in every person.'])
add('bio',5,'Vulnerability meets experience','BIO.05','p1-a','general',['causality','change'],
 'Explain the diathesis-stress model with reference to one example of behaviour or mental health.',[
 'The diathesis-stress model proposes that vulnerability and environmental stress interact in the development of an outcome. In an illustrative case, inherited vulnerability to an anxiety disorder might be present without the person developing the disorder. A demanding life transition could contribute to its expression alongside that vulnerability.',
 'Neither vulnerability nor stress should automatically be treated as independently sufficient. Support, coping resources and the nature of the stressor can alter the relationship. The model therefore explains why people exposed to a similar event may have different outcomes, without treating a genetic predisposition as destiny or assuming that every response to difficulty is a disorder.'])
add('bio',6,'Inheritance without inevitability','BIO.06','p1-a','general',['causality','measurement'],
 'Explain how genetic inheritance may influence one human behaviour, using an example.',[
 'Inherited variation can contribute to biological differences that affect the likelihood of a behaviour or vulnerability. For example, inherited influences may contribute to differences in sensitivity to stress. This is a probabilistic account: it does not require a single gene that directly specifies a person’s response to every difficult situation.',
 'Environmental experiences and development also shape the expression of inherited influences. Family resemblance alone does not separate shared genes from shared experiences, and population heritability is not the percentage of an individual’s behaviour caused by genes. A relevant example should explain the proposed inherited contribution while preserving this distinction between influence and determination.'],sources=[SOURCES['inheritance']])
add('bio',7,'Localizing a component of behaviour','BIO.07','p1-a','general',['measurement','perspective'],
 'Explain localization of function with reference to one example of cognition or behaviour.',[
 'Localization of function proposes that particular brain regions make specialized contributions to particular processes. For example, damage affecting left inferior frontal language regions, including Broca-associated areas and their connections, may disrupt fluent speech more than comprehension. Comparing the different components of performance can help identify the contribution of the affected region rather than treating language as an undivided ability.',
 'Specialization does not mean that one isolated region performs the entire behaviour. Connected regions, the nature of the task and changes following damage affect performance. The example should therefore link a specific component to a proposed region or network while avoiding the stronger and unjustified claim that complex cognition occupies a single self-contained brain location.'])
add('bio',8,'Experience and changing connections','BIO.08','p1-a','general',['change','causality'],
 'Explain neuroplasticity with reference to one example of cognition or behaviour.',[
 'Neuroplasticity is the capacity for the nervous system’s organization or functioning to change with experience or development. For example, repeated practice of an unfamiliar two-handed rhythm may alter the efficiency or organization of networks involved in coordinating the movement sequence. This offers a mechanism through which experience can contribute to later performance.',
 'Plasticity does not mean unlimited improvement or that every observed anatomical difference was caused by practice. Pre-existing differences and other experiences can also matter, and a structural scan does not reveal the exact microscopic change. The example should explain the experience-to-system-to-behaviour link rather than simply state that the brain changes whenever something is learned.'],sources=[SOURCES['plasticity']])

# Applied biological scenarios. The figures contain givens, not outcome graphs.
add('bio',9,'A fictional reuptake blocker','BIO.09','p1-b','health-wellbeing',['causality','measurement'],
 'In a fictional research model, a neuron releases messenger M into a synaptic gap. A carrier normally returns some M to the releasing cell. Compound Z blocks that carrier but does not manufacture M or directly activate the receiving cell’s receptors. Explain how neurotransmission could be affected, and why this action alone would not establish that Z improves a mental health disorder.',[
 'Blocking the return carrier could leave released messenger available in the synaptic gap for longer, changing its opportunity to bind to the receiving cell’s receptors. This depends on messenger already being released; the compound is not described as producing messenger or acting as a receptor agonist. Receptor activation changes the probability of subsequent neural activity.',
 'The relevant link to the scenario is altered clearance rather than increased manufacture. The resulting behavioural effect would depend on which circuits and receptors are involved and on other compensatory processes. More messenger in the gap does not automatically mean greater psychological well-being.',
 'A claim about clinical improvement requires evidence about meaningful symptoms, functioning and unwanted effects, not merely the biochemical action supplied here. The model explains a possible neural mechanism while leaving therapeutic effectiveness as a separate question. It would be incorrect to infer that the disorder must originally have been caused by too little M.'],fig=card_figure('Fictional synaptic model',[('Release','Cell A releases M'),('Gap','M can bind receptors'),('Return carrier','Z blocks recycling')]))
add('bio',10,'Similar transitions, different vulnerabilities','BIO.05','p1-b','health-wellbeing',['causality','change'],
 'A fictional counselling case describes two adults beginning equally demanding new jobs. One has a longstanding vulnerability to anxiety and little social support; the other has no identified vulnerability and strong support. The counsellor cautions that neither outcome is inevitable. Apply the diathesis-stress model to explain that caution.',[
 'The job transition is a possible stressor, while the longstanding vulnerability represents a diathesis. The model predicts that their interaction can alter the likelihood of anxiety rather than requiring the transition to affect both adults identically. Equal job demands do not ensure equivalent psychological or biological stress responses.',
 'Social support may reduce the impact of the demands or provide coping resources, so it can change how vulnerability and stress combine. The first adult is not certain to develop a disorder, and the second is not immune merely because no vulnerability has been identified. Vulnerability can also be incompletely measured.',
 'The counsellor’s caution is therefore central to the model: the case suggests interacting risks and protections, not a diagnosis or a deterministic prediction. An explanation based only on the job ignores individual vulnerability; an explanation based only on inheritance ignores the changing environment and available support.'],fig=card_figure('Fictional transition cases',[('Adult A','Vulnerability; little support'),('Adult B','No identified risk; support'),('Both','Demanding new job')]))
add('bio',11,'A one-circuit explanation','BIO.02','p1-b','health-wellbeing',['perspective','responsibility'],
 'A fictional wellbeing poster states: “Every panic episode is completely explained by an overactive threat circuit. Personal interpretations and social experiences add nothing.” Explain why the poster is biologically reductionist and how this affects its usefulness.',[
 'The poster reduces a complex experience to activity in one biological system and explicitly excludes other explanatory levels. A threat circuit can contribute to arousal, but the claim of complete explanation treats that contribution as sufficient for every panic episode. This is stronger than identifying a useful biological mechanism.',
 'The reduction may make a mechanism easier to investigate or suggest a possible treatment target. However, excluding interpretations and learning ignores why a sensation is experienced as threatening in a particular situation. Social experiences can also affect what is learned or appraised, even when biological processes are involved.',
 'Its usefulness is consequently restricted by its absolute language. A responsible explanation could retain the circuit contribution while considering cognitive and social influences. Simply replacing the poster with a claim that biology never matters would repeat the same error in the opposite direction rather than provide a better integrated account.'],fig=card_figure('Claim on a fictional poster',[('Included','One threat circuit'),('Excluded','Interpretations; experience')]))
add('bio',12,'Relearning speech after injury','BIO.08','p1-b','health-wellbeing',['change','perspective'],
 'In a fictional rehabilitation case, an adult who lost some speech ability after a brain injury gradually improves during repeated, supported language practice. Explain how neuroplasticity offers one account of the improvement, without assuming that the injured tissue simply returns to its original state.',[
 'Repeated practice may strengthen or reorganize functioning connections within the remaining language system. Networks that previously made a smaller contribution may become more involved, and the person may develop compensatory ways of producing speech. These are examples of functional change rather than proof that damaged tissue has been completely restored.',
 'The account connects the repeated, supported language activity to opportunities for adaptation. Support can make practice possible and feedback can help the person use successful strategies. The improvement could therefore involve an interaction between biological capacity and an enriched learning environment rather than a purely automatic recovery process.',
 'Plasticity is one explanation, not a guarantee of full recovery. Injury severity, time and other assistance may also influence the course. Observing improvement during practice cannot by itself establish exactly which neural connections changed; the behavioural observation supports a possible mechanism that would need further investigation.'],fig=card_figure('Fictional rehabilitation timeline',[('Initial injury','Speech becomes difficult'),('Supported practice','Repeated language activity'),('Later assessment','Some ability improves')]),sources=[SOURCES['plasticity']])
add('bio',13,'Practice during development','BIO.08','p1-b','human-development',['change','causality'],
 'A fictional child begins learning tactile reading. Lessons repeatedly pair patterns felt by the fingertips with spoken words, and the child becomes more efficient at recognizing the patterns. Explain how environmental experience and neuroplasticity could interact in this development.',[
 'The lessons provide repeated, meaningful sensory and language experiences. Neuroplasticity offers an account in which the organization or functioning of relevant neural connections changes through this activity. Improved recognition could reflect more efficient coordination of tactile information with learned word representations rather than simply a fixed ability unfolding without experience.',
 'The environmental input is specific: repeated pairings, instruction and feedback give the child opportunities to build and refine the skill. The child’s developing nervous system makes such learning possible, while the structured experience influences what is learned. Biology and environment are therefore interacting rather than competing explanations.',
 'The account does not imply that the child acquires extra brain tissue in a particular location or that every child will progress identically. Prior experience and the quality of support may affect the process. What is justified is a mechanism connecting repeated experience to adaptation and increasingly effective behaviour.'],fig=card_figure('Fictional learning sequence',[('Touch','Tactile pattern'),('Instruction','Spoken word and feedback'),('Practice','Repeated recognition')]))
add('bio',14,'A developmental animal comparison','BIO.01','p1-b','human-development',['perspective','responsibility'],
 'A fictional research team uses a carefully controlled animal model to investigate how early sensory experience affects later discrimination. A journalist calls the model “a complete account of human childhood development”. Explain why animal evidence may be valuable but the journalist’s description is too strong.',[
 'The model can isolate a relationship between early experience and a later perceptual ability under conditions that would be difficult or unethical to impose on children. If relevant biological processes are shared, the findings may suggest a mechanism or a question to examine using ethical human methods.',
 'However, sensory discrimination in the model is a selected component of development, not the whole of human childhood. Human language, caregiving, schooling and culture can change how experience influences later behaviour. The model’s controls may increase precision while also making the setting less representative of ordinary development.',
 'The journalist therefore overextends the model. Responsible interpretation would state which process the model represents, consider species differences and seek converging human evidence. Its possible value does not automatically justify every animal procedure; welfare and the necessity of the research require a separate ethical evaluation.'])
add('bio',15,'Inherited differences and a new language','BIO.06','p1-b','human-development',['causality','perspective'],
 'In a fictional discussion, a parent says that a child’s language development is already fully specified by inherited characteristics, so opportunities to communicate cannot matter. Explain how an account of genetic inheritance can acknowledge biological influences without supporting the parent’s conclusion.',[
 'Inherited variation can influence biological characteristics relevant to language development, such as aspects of sensory or cognitive functioning. That is an influence on development, not a complete inherited specification of the words, language or interactions the child will acquire. The parent moves from a possible contribution to an unsupported deterministic conclusion.',
 'Communication opportunities provide experiences through which a language is learned and used. The child’s biological capacities and the environment can interact: the effect of an experience may depend on the child, and inherited capacities may be expressed differently in different learning conditions.',
 'A reasoned account therefore keeps biological influence while rejecting the claim that experience is irrelevant. It also avoids assigning an individual a fixed amount of “genetic language ability” from population research. The scenario supports considering both inherited variation and opportunities for interaction, rather than using inheritance as a reason to withdraw educational support.'],sources=[SOURCES['inheritance']])
add('bio',16,'Two components of language','BIO.07','p1-b','human-development',['measurement','change'],
 'A fictional assessment describes Child A as having difficulty producing fluent speech while understanding many spoken instructions. Child B has fluent speech but struggles to understand the instructions. Both have different, documented brain injuries. Explain how these contrasting profiles could support localization of function, while leaving room for development and networks.',[
 'The contrasting profiles separate language production from aspects of comprehension. If different injuries are consistently associated with the different difficulties, this supports the view that brain systems make specialized contributions rather than all language functioning as a single undifferentiated ability.',
 'The inference concerns components and their relationships to affected regions or connections. It does not show that either injury removed a complete “language box”. Each task also involves attention, sensory processing and connected regions, so the assessment would need to establish that the apparent contrast is not explained by an unrelated difficulty.',
 'Because these are children, development and adaptation may alter the relationship between injury and later performance. Localization can therefore guide investigation without predicting a permanently fixed outcome. The two profiles provide a reason to study specialization and networks together, not a basis for diagnosing a precise anatomical lesion from a brief description alone.'],fig=card_figure('Fictional language profiles',[('Child A','Fluency difficult; understands'),('Child B','Fluent; understanding difficult')]))

add('bio',17,'The same messenger in different relationships','BIO.04','p1-b','human-relationships',['perspective','causality'],
 'A fictional team proposes that messenger M changes how strongly a person attends to social cues. Its model predicts different responses when the same cue comes from a trusted friend or an unfamiliar rival. Explain why this proposal is compatible with a chemical-messenger explanation rather than requiring M to produce identical behaviour in every relationship.',[
 'A chemical messenger acts through receptors and neural systems; it does not contain a complete instruction specifying how to behave toward every person. If M changes attention to social cues, the effect of that changed processing can depend on what the cues mean in the particular relationship.',
 'A trusted friend and an unfamiliar rival can evoke different expectations and appraisals. Greater attention might therefore make reassurance more influential in the first relationship but make a possible threat more noticeable in the second. These are conditional illustrations of the supplied model, not asserted findings about a named real chemical.',
 'The proposal combines a biological mechanism with the social information processed by that mechanism. It would be too strong to describe M as a universal “trust chemical” or to infer identical responses from identical availability. Testing the proposal would require appropriate measures of attention and behaviour in the different contexts.'],fig=card_figure('Fictional social-cue model',[('Same M','Proposed effect on attention'),('Friend','Cue within trusted relationship'),('Rival','Cue within unfamiliar rivalry')]))
add('bio',18,'Injury is not an entire relationship','BIO.02','p1-b','human-relationships',['perspective','responsibility'],
 'In a fictional family case, an adult becomes less able to regulate some impulsive responses after a documented brain injury. A relative claims that every later disagreement is therefore caused by damaged tissue and that communication can have no influence. Explain the reductionism in this claim while acknowledging a possible biological contribution.',[
 'The injury may affect systems involved in regulating responses, so a biological explanation can contribute to understanding the change. The relative becomes reductionist by treating that contribution as a sufficient explanation of every disagreement and excluding interpersonal processes in advance.',
 'Disagreements also depend on what people say, what the situation demands and how other people respond. Communication may alter the triggers, available coping strategies or consequences of an impulsive response without reversing the injury. A biological constraint and a meaningful environmental influence can therefore exist together.',
 'The appropriate conclusion is neither that the injury is irrelevant nor that the person has become a passive product of damaged tissue. A more useful account distinguishes the affected regulatory process from the content and context of particular conflicts, while avoiding blame or confident clinical predictions based on a short description.'])
add('bio',19,'One signal, different receiving systems','BIO.09','p1-b','human-relationships',['causality','measurement'],
 'A fictional neural model gives messenger M two effects: binding at receptor R1 increases the activity of receiving Cell A, while binding at R2 reduces the activity of receiving Cell B. Both cells contribute to a network involved in social responses. Explain why increasing available M would not, by itself, justify predicting a uniform increase in a particular social behaviour.',[
 'Neurotransmission depends on the interaction between the messenger and the receiving receptor system. The supplied model explicitly gives different consequences at R1 and R2. An increase in available M could therefore influence the two receiving cells in different directions rather than simply make every cell more active.',
 'The social response depends on the contribution and interaction of cells within the wider network. Changes in one component need not translate directly into a proportional increase in a whole behaviour. The balance of receptor availability, release and clearance, together with the activity of other connections, is relevant to the prediction.',
 'Consequently, identifying a messenger concentration is not enough to specify a unique social outcome. The scenario is a fictional illustration of receptor-dependent action, not evidence that all messengers have these particular effects. A justified behavioural prediction would need a more developed model and evidence about the network and context.'],fig=card_figure('Given receptor-dependent model',[('Messenger M','Available to both receptors'),('R1 on Cell A','Activity increases'),('R2 on Cell B','Activity decreases')]))
add('bio',20,'Resemblance after adoption','BIO.06','p1-b','human-relationships',['causality','bias'],
 'A fictional account describes an adopted adult who shares a tendency to hesitate in unfamiliar social settings with a biological parent, but whose close relationships differ greatly from that parent’s. Explain how genetic inheritance could be relevant without assuming that either the resemblance or the difference establishes a complete genetic explanation.',[
 'Inherited variation might contribute to a disposition relevant to responses in unfamiliar settings. The resemblance is compatible with such an influence, but a brief case cannot determine which biological mechanisms are involved or separate inherited effects from other possible similarities.',
 'Close relationships develop through interactions, learning and particular social environments. A disposition need not produce an identical relationship pattern in different circumstances. The adult’s different relationships are therefore compatible with an inherited influence that is expressed or managed differently, rather than automatically disproving inheritance.',
 'The two observations do not justify assigning a genetic percentage to this individual or concluding that a social trait is fixed. A balanced account considers inherited predispositions alongside development and experience. Stronger evidence would require an appropriate research design, not selective use of whichever part of the family story supports a preferred explanation.'],sources=[SOURCES['inheritance']])
add('bio',21,'Learning a new movement sequence','BIO.08','p1-b','learning-cognition',['change','measurement'],
 'A fictional learner practises an unfamiliar sequence of hand movements with feedback. The sequence becomes easier to perform without consciously considering every movement. Explain how neuroplasticity could help account for the change, and why improved performance alone would not identify a particular anatomical change.',[
 'Repeated coordinated activity can provide opportunities for the functioning or organization of relevant neural connections to change. A plasticity account connects experience with increasingly effective processing, allowing the movement sequence to be performed with less effortful control than at the start.',
 'Feedback helps the learner adjust errors and repeat successful actions. These experiences can influence which patterns of processing are practised, so the biological explanation is linked to the learning environment rather than offered as an alternative to practice. It does not require that a new isolated “movement centre” appears.',
 'The behavioural improvement does not reveal whether any specific tissue volume, synaptic property or network connection changed. Strategy changes and familiarity may also contribute to performance. Appropriate biological measurements would be needed to investigate the neural mechanism, and even a scan would need interpretation rather than being treated as a direct picture of learning.'],fig=card_figure('Fictional practice sequence',[('New sequence','Deliberate individual movements'),('Practice','Feedback and repetition'),('Later performance','Sequence feels more fluent')]),sources=[SOURCES['plasticity']])
add('bio',22,'Specialization inside an overlapping network','BIO.07','p1-b','learning-cognition',['perspective','measurement'],
 'A fictional teaching model represents a word-retrieval task as involving components A and B, and a planning task as involving B and C. The components are connected. A student says that the overlap makes localization of function impossible. Explain why that conclusion does not follow.',[
 'Localization can refer to specialized contributions to parts of a process, rather than exclusive ownership of an entire task by one area. Component B could contribute something used in both tasks, while A and C make other contributions. Shared involvement therefore does not eliminate the possibility of specialization.',
 'The connected model also illustrates why a task should not be equated with one self-contained brain location. Word retrieval and planning may each require several interacting processes. To investigate localization, researchers would need to clarify what each component contributes and distinguish the target process from the other demands of the task.',
 'The diagram is a hypothetical model, not evidence that these exact components exist in these locations. It supports considering specialization and distributed processing together. The student treats an overly strong version of localization as the only possible account, so rejecting that version does not settle the broader question of functional organization.'],fig=card_figure('Fictional component model',[('Word retrieval','Components A and B'),('Planning','Components B and C'),('Connections','Components interact')]))
add('bio',23,'A maze is a model of a process','BIO.01','p1-b','learning-cognition',['perspective','responsibility'],
 'A fictional laboratory uses an animal navigation task to investigate how changing available landmarks affects learning. An education company wants to use the model alone to decide how human reading should be taught. Explain the value of the animal model and the problem with this proposed application.',[
 'The laboratory can control landmarks and other conditions to investigate a selected learning process. If relevant spatial or neural mechanisms are shared, the model may generate a hypothesis about how information supports learning. This can contribute to a broader understanding of cognition without requiring the task to imitate every feature of human life.',
 'Reading, however, involves language, instruction and cultural experience that are not represented simply by navigation among landmarks. An effect in the animal task does not by itself establish the best human teaching method. The education company is moving from a selected process to a different complex behaviour without demonstrating the necessary connection.',
 'The model’s appropriate role is therefore to inform questions and mechanisms, followed by relevant human evidence about reading and educational outcomes. This limitation does not make all animal evidence worthless, but it restricts the claimed application and makes transparent reporting of what was and was not modelled a responsibility.'],fig=card_figure('Fictional translation proposal',[('Animal task','Landmarks and navigation'),('Proposed use','Choose reading instruction')]))
add('bio',24,'The brain-only learning claim','BIO.02','p1-b','learning-cognition',['perspective','change'],
 'A fictional learning service argues that a child’s reading difficulties are fully explained by a brain measure. It therefore offers the same exercise to every child and ignores their language experience or classroom support. Apply biological reductionism to explain one attraction and one limitation of this approach.',[
 'The approach is biologically reductionist because it treats one brain measure as a sufficient account of a complex learning difficulty. Its attraction is that a specified biological mechanism can guide focused investigation and make the proposed explanation appear more precise than a broad description of reading problems.',
 'However, the same reading performance can arise through different interacting influences. Language experience, instruction and support may affect learning even when biological differences are present. Offering the same exercise to everyone assumes that the measure identifies both the cause and the appropriate intervention, neither of which follows simply from its biological status.',
 'An integrated account would retain relevant biological information while examining how it interacts with the learner’s experiences and educational environment. The limitation is not that a brain measure can never be useful. It is that the service turns a possible contribution into a complete explanation and a uniform solution without showing that the extra inferences are justified.'],fig=card_figure('Fictional service proposal',[('One measure','Used as full explanation'),('One exercise','Given to every learner'),('Not considered','Language and support')]))

# Concept-based biological essays: five developed paragraphs each.
add('bio',25,'Reductionism and responsible treatment','BIO.02','p1-c','health-wellbeing',['perspective','responsibility'],
 'To what extent can biological reductionism support responsible explanations and treatment of one mental health disorder?',[
 'Biological reductionism can support responsibility when it identifies a plausible mechanism rather than presenting a disorder as a moral failing. For a selected disorder such as major depressive disorder, an account of neural signalling may help organize research and identify possible treatment targets. Precision can make an explanation testable and help clarify what a proposed intervention is intended to change.',
 'That contribution should be separated from the claim that a disorder has one sufficient biological cause. Symptoms, meanings and functioning can vary, and similar biological processes may participate in different experiences. Treatment response does not logically demonstrate that the disorder was originally caused by a simple deficiency of the substance affected by the treatment.',
 'Responsibility also concerns the person receiving care. Explanations need to communicate uncertainty and avoid portraying an individual as an inevitable product of a brain abnormality. A biological account may reduce blame, but a deterministic presentation may increase pessimism or discourage attention to relationships, learning and material circumstances that can also be relevant.',
 'An alternative perspective is that integrated explanations are too broad to guide action. This criticism has force if integration merely lists unrelated factors. It is weaker when cognitive, biological and social accounts make distinct, testable predictions and inform decisions about outcomes that matter to the person, including functioning and unwanted effects.',
 'Biological reductionism is therefore useful to a qualified extent: it can provide a disciplined level of explanation and contribute to treatment development. It becomes less responsible when its explanatory level is mistaken for a complete account of the disorder or an automatic treatment recommendation. A justified conclusion preserves mechanism while assessing evidence, alternatives and individual context.'])
add('bio',26,'What a scan can establish','BIO.03','p1-c','health-wellbeing',['measurement','causality'],
 'Discuss the relationship between measurement and causality when brain imaging is used to understand a mental health disorder.',[
 'Measurement makes a proposed biological explanation observable, but the kind of measure determines the inference it can support. Structural MRI can describe anatomical features, while fMRI uses an indirect physiological signal during tasks. Neither should be treated as a direct photograph of a disorder, and a difference in one measure does not automatically identify its cause.',
 'For example, a hypothetical comparison between people with and without an anxiety disorder could reveal an association involving a particular brain system. The difference might contribute to vulnerability, develop through experience of the disorder or reflect another influence. A well-reproduced measurement can therefore be reliable without establishing which causal direction is correct.',
 'Stronger designs can improve causal reasoning. Measurements before and after an intervention, suitable comparison conditions and converging behavioural evidence may help test a mechanism. However, a change in a scan occurring alongside improvement still requires attention to other changes, such as practice with the task or expectations about treatment. Measurement quality and design both matter.',
 'An opposing concern is that these limitations make imaging uninformative. That conclusion is also excessive: imaging can constrain a theory, distinguish competing predictions and reveal relationships unavailable to self-report alone. Its value is greatest when the task, biological signal and behavioural construct are explicitly connected rather than when a coloured region is used as a complete explanation.',
 'The relationship is thus interdependent. Appropriate measurement is necessary for testing a causal claim, but no measurement technique alone supplies a causal design. A proportionate account uses the scan as one form of evidence, explains what it represents and combines it with other methods before concluding why the disorder develops or changes.'],fig=card_figure('Two hypothetical research questions',[('Measurement','What does the scan represent?'),('Causality','Why did the difference arise?')]),sources=[SOURCES['imaging']])
add('bio',27,'Inheritance and changing prevalence','BIO.06','p1-c','health-wellbeing',['change','causality','measurement'],
 'Evaluate genetic inheritance as an explanation of changes in the recorded prevalence of an anxiety disorder within a population.',[
 'Genetic inheritance can help explain differences in vulnerability, but a change in recorded prevalence is not automatically a change in inherited risk. Prevalence is a measure of identified cases in a population at a particular time. It depends both on the experiences people have and on how cases are recognized and recorded.',
 'An inherited influence could interact with changing environmental conditions. If a population encounters new stressors or loses protective support, an existing distribution of vulnerabilities may be expressed differently. The diathesis-stress framework therefore allows genetic influence without requiring a rapid change in the population’s genetic composition to explain every change in disorder prevalence.',
 'Measurement introduces another explanation. Increased recognition, access to services or changes in the application of diagnostic criteria could alter recorded prevalence even if underlying experience changed less. Researchers should distinguish these possibilities rather than treat a difference between records as direct evidence that a genetic cause has become more common.',
 'The counterargument is that dismissing genetics whenever prevalence changes overlooks genuine inherited contributions and possible changes in population composition. This is reasonable: inherited variation can remain relevant, and populations are not necessarily static. Nevertheless, a genetic explanation would need evidence connecting those changes to the specific prevalence pattern, rather than relying on a general heritability estimate.',
 'Genetic inheritance is consequently a potentially important component but an insufficient explanation on its own. A stronger account connects inherited vulnerability with environmental change and measurement practices. It avoids both genetic determinism and the equally unsupported claim that all recorded changes must be artefacts, reaching a qualified judgement about what further evidence is needed.'],sources=[SOURCES['inheritance']])
add('bio',28,'Animal models and responsibilities in treatment research','BIO.01','p1-c','health-wellbeing',['responsibility','perspective'],
 'Examine how responsibility should influence the use and interpretation of animal models in research intended to improve mental health treatment.',[
 'Responsibility concerns both how knowledge is produced and how its significance is represented. Animal models can allow investigation of selected neural or behavioural mechanisms under controlled conditions. In treatment research, this may identify a biological process worth studying further without exposing human participants to an inadequately understood intervention.',
 'That potential benefit does not remove the responsibility to justify animal use. A defensible project should explain why the question matters, why suitable alternatives cannot answer it, and how unnecessary harm and the number of animals are minimized. Merely naming a possible future treatment is not enough to establish that any procedure is proportionate.',
 'Interpretation carries a separate responsibility. A model may capture one response relevant to a disorder without reproducing its subjective experience, language or social context. Describing an animal’s behaviour as identical to a human diagnosis can obscure those limits. A careful account identifies which component is modelled and which human claims remain untested.',
 'One counterargument is that requiring perfect translation would prevent valuable work, since every model simplifies. This is persuasive as a criticism of an impossible standard, but it does not justify ignoring translation. Models can be useful when their assumptions are explicit and when later human investigation tests whether the mechanism has comparable relevance.',
 'Responsibility should therefore shape question selection, welfare protections and communication of conclusions. It does not imply that all animal research is either automatically acceptable or automatically useless. The strongest judgement weighs the specific scientific necessity and likely benefit against harms, while keeping treatment claims narrower than the evidence actually supplied by the model.'])
add('bio',29,'Recovery and localization in childhood','BIO.07','p1-c','human-development',['change','perspective'],
 'To what extent can localization of function account for changes in a child’s abilities after a brain injury?',[
 'Localization of function can explain why an injury affects some abilities more than others. If a damaged region or connection contributes especially to a component of language, for instance, a child may have a particular difficulty with that component rather than losing every cognitive ability. This provides a useful starting point for understanding the initial pattern of change.',
 'However, complex abilities depend on connected systems. A language difficulty may reflect a disruption in communication between regions, and performance on an assessment can also depend on attention, hearing and task familiarity. The relation between a location and an observed behaviour is therefore more complex than a one-to-one map between an isolated brain part and an entire ability.',
 'Development introduces further change. Remaining systems may adapt through neuroplasticity, while maturation and supported learning can alter how a task is performed. Improvement need not mean that the original specialization was imaginary; it may mean that the nervous system has changed or that a different strategy now supports performance.',
 'A counterargument is that emphasizing plasticity makes localization impossible to test. This would follow only if every outcome were explained after the event without constraints. Researchers can instead make specific predictions about components, timing and recovery, then use converging behavioural and biological observations to compare localized and distributed accounts.',
 'Localization therefore accounts for part of the explanation, especially selective initial impairments, but it is not a complete developmental prediction. A qualified conclusion considers specialization, connections and adaptation together. It avoids both the claim that the injury fixes the child’s future permanently and the claim that the developing brain can always reorganize without limits.'])
add('bio',30,'A developmental vulnerability model','BIO.05','p1-c','human-development',['causality','change','perspective'],
 'Discuss how the diathesis-stress model changes the explanation of differences between children who experience a similar life transition.',[
 'The model changes the causal question from whether the transition alone produces a particular outcome to how the transition interacts with vulnerability and protective conditions. Two children can experience an apparently similar move, school change or family adjustment without having identical histories, appraisals or resources. The external event is therefore not necessarily the same psychological experience for each child.',
 'A diathesis may involve inherited or previously developed vulnerability, while stress can arise from the demands of the transition. Their interaction provides an explanation for divergent responses without requiring one child to be entirely unaffected by biology and the other entirely controlled by it. This is a probabilistic framework rather than a fixed diagnostic threshold that applies identically to everyone.',
 'Change also occurs within the interacting factors. Social support, coping opportunities and later experiences may reduce or intensify the impact of the transition. A developmental explanation should therefore consider processes over time rather than assigning a stable label to a child from an early response. Protection is not simply the absence of a vulnerability.',
 'The model can be criticized for becoming difficult to test if any outcome is retrospectively attributed to an unspecified combination of factors. This limitation makes clear definitions important: researchers should identify the proposed vulnerability, stressor and outcome before interpreting their relationship. A broad interaction claim gains explanatory value only when it leads to informative predictions.',
 'The model is thus useful because it replaces a single-event or single-gene account with an account of interacting influences. Its strength depends on how those influences are specified and investigated. A justified conclusion recognizes different developmental pathways while avoiding inevitable predictions, blame for the child’s response or a claim that every difficult transition necessarily produces a disorder.'])
add('bio',31,'Measuring development responsibly','BIO.03','p1-c','human-development',['measurement','responsibility','bias'],
 'Evaluate the use of brain imaging as a measure of human development, considering responsibility toward the children being studied.',[
 'Brain imaging can provide a view of biological development that complements observations of behaviour. Structural images can investigate anatomy, while suitable functional tasks can examine physiological activity associated with processing. Their value depends on the match between the imaging measure and the developmental question; a technically impressive image is not automatically a valid measure of a child’s overall development.',
 'Tasks and comparisons need particular care with children. Differences in understanding instructions, movement during scanning or familiarity with the setting can affect what is measured. A group difference may therefore partly reflect the measurement situation rather than the proposed developmental process. Researchers should make these possibilities visible instead of treating an image as an interpretation-free fact.',
 'Responsibility includes age-appropriate assent, parental permission where appropriate, privacy and the child’s ability to stop. Investigators should also consider how unexpected findings are handled and how results are explained. A group-level pattern should not be turned into a confident prediction of an individual child’s educational potential or future personality.',
 'It can be argued that these safeguards make research more difficult and that avoiding imaging would also deny children potential benefits from improved knowledge. This supports proportionate rather than absolute restrictions. Good preparation and careful design can improve comfort and measurement together, while different methods may answer some questions with fewer demands on participants.',
 'Imaging is therefore a valuable but partial developmental measure. Responsible use requires both ethical safeguards and modest interpretation of the biological signal. The strongest approach combines imaging with appropriate behavioural evidence, explains uncertainties and judges the technique by what it contributes to understanding development rather than by the visual authority of the scan.'],fig=card_figure('Fictional developmental scan project',[('Child','Understanding and assent'),('Measurement','Task and imaging signal'),('Use of findings','Privacy and careful explanation')]),sources=[SOURCES['imaging']])
add('bio',32,'Translating early social experience','BIO.01','p1-c','human-development',['perspective','responsibility','measurement'],
 'Examine the relationship between perspective and responsibility when animal models are used to explain the role of early social experience in human development.',[
 'An animal model selects particular aspects of early social experience and later behaviour. It can support a biological perspective by allowing a proposed developmental mechanism to be investigated under controlled conditions. However, selecting what represents social contact, stress or later functioning already involves theoretical decisions rather than a neutral reproduction of human childhood.',
 'The human developmental question can include language, cultural expectations and a child’s interpretation of relationships. These features may be absent or very differently expressed in the model. A perspective that treats all species’ social behaviour as identical risks overlooking what the operational measures capture and what they leave out.',
 'Responsibility therefore includes clear communication of the model’s scope. A result concerning one animal behaviour should not be described as a complete explanation of human attachment, nor used alone to prescribe caregiving practices. Ethical human observations and other evidence are needed to test whether the proposed process has comparable meaning in children’s lives.',
 'At the same time, rejecting the model solely because it is not human can ignore shared biological systems and useful mechanistic questions. The appropriate comparison is not between a perfect model and a flawed one, but between alternative ways of answering a well-specified question. Any scientific benefit must still be weighed against animal welfare and the availability of less harmful approaches.',
 'Perspective and responsibility are thus linked: the assumptions about what is being modelled determine both the scientific inference and the risk of misleading applications. A balanced conclusion recognizes possible contributions while demanding justified animal use, explicit limits and converging human evidence before generalizing to development in a particular cultural or interpersonal setting.'])

add('bio',33,'Chemical explanations in changing relationships','BIO.04','p1-c','human-relationships',['perspective','change','causality'],
 'To what extent can an explanation based on chemical messengers account for changes in human relationships?',[
 'Chemical messengers can contribute to processes involved in attention, arousal and social responses. A biological explanation may therefore identify a mechanism through which the conditions of a relationship influence behaviour. For example, a model could propose that a messenger changes sensitivity to social cues rather than directly determining whether a person forms or maintains a relationship.',
 'Such an explanation can connect experiences with changes in the nervous or endocrine system, but the connection is not a complete description of a relationship. Relationships involve memories, expectations, communication and the actions of more than one person. The same physiological influence can operate on different social information, producing different responses rather than a single universal effect.',
 'The concept of change also requires attention to timescale. A temporary change in arousal during one interaction is not equivalent to a lasting change in attachment or commitment. Researchers need measures that distinguish momentary responses from relationship development. Otherwise an explanation can appear convincing by moving between outcomes that are not actually the same construct.',
 'A counterargument is that social accounts also rely on biological systems and therefore cannot exclude chemical mechanisms. This is correct, but dependence on a biological system does not mean its description alone explains the meaning of every interaction. The useful question is what additional predictions the chemical account makes and whether evidence connects those predictions to the relationship outcome.',
 'Chemical-messenger accounts consequently explain some contributing processes but are insufficient as standalone explanations of relationship change. A stronger conclusion integrates biological mechanisms with interpersonal history and context, matches measurements to the relevant timescale and avoids turning a proposed messenger effect into a simplistic label such as a universal cause of trust, conflict or affection.'])
add('bio',34,'Aggression and competing explanatory levels','BIO.02','p1-c','human-relationships',['perspective','causality','responsibility'],
 'Discuss the value and limitations of biological reductionism for explaining interpersonal aggression.',[
 'Biological reductionism can identify specific processes that contribute to aggressive responses, such as systems involved in arousal or behavioural regulation. This may make a theory more precise and testable than an explanation that merely repeats that a person is aggressive. It can also challenge the assumption that every difficulty in regulation is simply a freely chosen moral failure.',
 'However, interpersonal aggression is not defined solely by arousal. The interpretation of another person’s action, learned responses, norms and immediate opportunities can influence whether arousal results in aggression, withdrawal or negotiation. A complete explanation must therefore connect a proposed biological process to the particular behaviour rather than equating a bodily state with an aggressive act.',
 'Responsibility raises an additional problem. An account that portrays a group as biologically destined for aggression can stigmatize individuals and discourage attention to changeable conditions. Conversely, denying all biological contributions can overlook relevant constraints on behaviour and opportunities for support. Neither conclusion follows automatically from identifying a biological association.',
 'One defence of reductionism is that focusing on a component is necessary for controlled research. This is a strong argument for methodological focus, but not for treating the component as sufficient. A controlled investigation of one process can remain valuable while acknowledging that its significance depends on interaction with cognitive and sociocultural processes outside the simplified model.',
 'Biological reductionism is therefore useful as a constrained research perspective, but limited as an exhaustive explanation of interpersonal aggression. A justified judgement considers what the proposed mechanism explains, the alternatives that remain and the consequences of applying the account to individuals. Integration is strongest when it connects mechanisms rather than simply lists unrelated causes.'])
add('bio',35,'Genetic information and social prediction','BIO.06','p1-c','human-relationships',['responsibility','bias','causality'],
 'Evaluate the claim that inherited influences on behaviour justify using genetic information to predict an individual’s future relationship behaviour.',[
 'Inherited influences can contribute to characteristics relevant to social behaviour, but this does not establish that genetic information predicts a particular person’s relationships accurately. A population-level association concerns variation under particular conditions. It is not a complete causal account of an individual’s future communication, attachment or response to conflict.',
 'Relationship behaviour develops through interactions between people and their environments. Opportunities, experiences and the behaviour of others can alter how a disposition is expressed. A genetic account that ignores these processes risks converting a probabilistic contribution into a deterministic prediction, especially when the predicted outcome is broad or poorly defined.',
 'Bias can enter both measurement and application. A prediction developed in one population may reflect that population’s conditions, while a label can affect how others treat the person. Expectations may then influence opportunities and relationships, creating an apparent confirmation of the label that is partly produced by its social use rather than by the proposed inherited mechanism.',
 'A counterargument is that imperfect predictions can still be useful. That is possible in principle, but usefulness requires demonstrated accuracy, clear purposes and comparison with less intrusive alternatives. Genetic information is sensitive, so consent, confidentiality and the risk of stigmatization matter even where some predictive contribution is supported. Inheritance alone does not settle those responsibilities.',
 'The claim is therefore not justified in its general form. Evidence for inherited influence warrants further investigation, not an automatic entitlement to classify individuals’ relationship futures. A proportionate conclusion demands a well-defined outcome, relevant predictive evidence, attention to environmental interaction and ethical safeguards before considering any specific application.'],sources=[SOURCES['inheritance']])
add('bio',36,'Can a scan measure empathy?','BIO.03','p1-c','human-relationships',['measurement','perspective','responsibility'],
 'Examine the challenges of using brain imaging to measure empathy in human relationships.',[
 'Empathy includes processes that must first be defined before a scan can be interpreted as a measure of them. A task might involve recognizing another person’s emotion, taking a perspective or choosing a supportive response. These are related but not identical processes, so a measure of one should not automatically be presented as a complete measure of empathy in a relationship.',
 'Functional imaging can investigate physiological signals associated with a carefully designed task. However, activation in a region is not uniquely linked to one mental state. A task can also involve language, attention, memory and arousal. Inferring that a person must feel empathy merely because a region is active risks mistaking a possible association for a unique psychological signature.',
 'The relationship context also matters. Responding to a laboratory stimulus may differ from responding to a friend during a real disagreement. Converging evidence from behaviour or other measures can help evaluate whether the imaging result represents the intended construct. The purpose is not to rank methods by appearance, but to test how their interpretations connect.',
 'A defence of imaging is that self-report can be shaped by social desirability, so biological measures offer a useful alternative perspective. This is a real advantage when it provides complementary information, but an indirect biological measure is not automatically free of interpretive assumptions. Different sources of bias should be examined rather than assuming one technique removes them all.',
 'Imaging can therefore contribute to understanding components of empathy, but cannot simply read the quality of a relationship from a scan. Responsible measurement requires an explicit construct, an appropriate task, converging evidence and careful communication. A qualified conclusion preserves the technique’s contribution while rejecting confident individual labels that extend beyond the evidence.'],sources=[SOURCES['imaging']])
add('bio',37,'Plasticity and educational change','BIO.08','p1-c','learning-cognition',['change','responsibility','causality'],
 'To what extent does knowledge of neuroplasticity justify changing educational practice?',[
 'Neuroplasticity supports the general proposition that experience can contribute to changes in the nervous system. This is relevant to education because instruction and practice provide experiences through which skills develop. It challenges the claim that every learner’s future performance is completely fixed before teaching begins, but it does not identify a particular teaching method by itself.',
 'The step from mechanism to educational practice requires additional evidence. Two methods may both involve repeated neural activity while producing different kinds of learning. An observed brain change is not automatically a beneficial educational outcome, and a claim that an activity is “brain-based” does not establish that it improves understanding, retention or transfer.',
 'Responsibility therefore includes defining the educational goal and considering learners’ needs. A method might improve performance on a practised task without helping a new task, or place demands that are unsuitable in a particular setting. Schools should not use the language of plasticity to promise unlimited change or blame learners when improvement is difficult.',
 'An opposing view is that waiting for detailed biological evidence could delay useful classroom improvements. This criticism is reasonable: educational outcomes can justify a practice even when its exact neural mechanism is uncertain. Neuroplasticity may provide a compatible explanation, but the effectiveness of the educational practice still needs to be judged using relevant learning evidence.',
 'Knowledge of plasticity thus justifies openness to change and generates hypotheses about learning, but only partly justifies any specific reform. A stronger judgement combines plausible mechanisms with evidence about educational outcomes, implementation and opportunity costs. It avoids both fixed-potential pessimism and exaggerated claims that any activity changing the brain must be an effective teaching strategy.'],fig=card_figure('An educational inference to examine',[('Biological idea','Experience can change systems'),('Proposed practice','A new teaching method'),('Educational goal','Understanding and transfer')]),sources=[SOURCES['plasticity']])
add('bio',38,'A single location for memory?','BIO.07','p1-c','learning-cognition',['measurement','perspective'],
 'Discuss the claim that finding a brain region involved in memory shows that memory is stored in one location.',[
 'A finding that a region contributes to a memory task can support functional specialization, but the conclusion depends on what “memory” and “involved” mean. Learning a route, retaining a movement sequence and remembering an event place different demands on the person. Treating them as one identical process can make a localization claim broader than the task actually examined.',
 'A region may contribute to encoding new information, retrieving it or coordinating connections rather than acting as a self-contained store. For example, a memory-related system can be necessary for some aspects of a task while the representation also depends on other networks. Evidence of involvement should therefore be distinguished from evidence that all relevant information resides exclusively there.',
 'Measurement affects the inference. Functional activation associates a signal with a task, while injury evidence can reveal difficulties when part of a system is disrupted. Each has limitations, including other task demands and consequences of damage to connections. Converging approaches can strengthen a theory, but their different forms of evidence should not be treated as interchangeable.',
 'A defence of the single-location view is that selective impairment suggests specialized organization. This is an important observation, yet specialization is compatible with a distributed system containing components with different roles. The strongest test compares specific predictions about processes and connections instead of choosing between the slogans that memory is either entirely local or entirely everywhere.',
 'The original claim is consequently too strong. Identifying a contributing region advances understanding, but does not by itself establish an exclusive storage location for every form of memory. A justified conclusion specifies the memory process, the type of biological evidence and the possible network contribution, preserving useful localization without collapsing complex cognition into a single anatomical box.'],fig=card_figure('Different memory questions',[('Learning','Acquiring a new route'),('Retrieval','Using a familiar route'),('Other tasks','Remembering actions or events')]),sources=[SOURCES['plasticity'],SOURCES['imaging']])
add('bio',39,'Inherited influence and educational potential','BIO.06','p1-c','learning-cognition',['causality','bias','responsibility'],
 'Evaluate the claim that evidence of genetic inheritance makes an individual learner’s educational potential fixed.',[
 'Evidence of inherited influence can explain some variation in characteristics relevant to learning, but “educational potential” is a broad prediction about a person’s future. A genetic contribution observed in a population does not directly establish that future performance is unchangeable. It describes a relationship under particular conditions, not a complete account of every possible educational environment.',
 'Heritability concerns variation within a studied population and context. It is not a percentage of an individual’s ability that can be separated from experience, and a substantial inherited contribution does not logically show that an intervention cannot matter. Changes in instruction, opportunity and support can alter how learners develop and express their capacities.',
 'Bias can arise when expectations influence educational decisions. A fixed-potential label may reduce access to challenging work or support, affecting later performance and appearing to validate the original assumption. Responsibility therefore requires distinguishing evidence about inherited variation from the consequences of using that evidence to restrict an individual’s opportunities.',
 'The counterargument is that denying inherited differences can create unrealistic expectations that everyone will respond identically to the same instruction. This is persuasive against an equally absolute environmental account. Recognizing differences may help tailor support, but it does not establish a precise limit for an individual or justify assuming that an observed difficulty cannot change.',
 'The fixed-potential claim is therefore unjustified. A balanced conclusion recognizes inherited influences while treating learning as developmental and context-sensitive. It asks what a particular measure predicts, for whom and under which conditions, rather than turning a population explanation into a deterministic educational judgement. This position avoids both genetic fatalism and the promise of unlimited improvement.'],sources=[SOURCES['inheritance']])
add('bio',40,'Control and translation in learning research','BIO.01','p1-c','learning-cognition',['causality','responsibility','perspective'],
 'Examine how causal control and responsibility can come into tension when animal models are used to explain human learning.',[
 'Causal control can make an animal model informative by allowing a proposed learning mechanism to be investigated while other conditions are held relatively stable. A carefully specified change in cues or experience may help distinguish competing explanations. This is different from merely observing that two naturally occurring characteristics are associated.',
 'However, increasing control may also increase the difference between the model and human learning outside the laboratory. Human learning can involve language, prior knowledge, cultural practices and personal goals that are not captured by a simplified task. A causal relationship within the model does not automatically establish the same relationship for a different behaviour in a classroom.',
 'Responsibility introduces a second tension. Some highly controlled manipulations may create unacceptable harm or have ethical alternatives. Scientific interest in isolating a variable is not sufficient justification for every procedure. The value of the question, the necessity of using animals and possibilities for reducing harm need explicit consideration alongside the design’s causal strengths.',
 'The counterargument is that less controlled human studies can leave important mechanisms unresolved, which also has costs when ineffective educational claims spread. This supports carefully justified research, not unrestricted experimentation. Converging methods can divide the problem: a model investigates a limited process while suitable human work tests whether the process explains relevant learning outcomes.',
 'Control and responsibility are therefore related rather than simply opposing goals. Responsible research seeks enough control to answer a worthwhile question, avoids disproportionate harm and communicates the limits of translation. A strong conclusion values causal evidence within the model while requiring additional justification before turning it into a broad claim about how people should learn.'])

# Cognitive knowledge: examples are illustrative, not purported study findings.
add('cog',1,'An initial numerical reference','COG.01','p1-a','general',['bias','measurement'],
 'Explain anchoring bias with reference to one example of a judgement.',[
 'Anchoring bias occurs when an initial reference has an inappropriate influence on a later judgement, often because adjustment away from it is insufficient. For example, someone estimating how long an unfamiliar journey will take may give excessive weight to an arbitrary duration mentioned before they consider the actual route.',
 'The example requires more than simply using prior information: relevant information can reasonably inform an estimate. The bias is the disproportionate influence of a reference that is not justified by the available evidence. Explaining why the initial duration remains influential distinguishes anchoring from a general statement that people sometimes make inaccurate predictions.'
 ],sources=[SOURCES['anchoring']])
add('cog',2,'Learning an association between stimuli','COG.02','p1-a','general',['change','causality'],
 'Explain classical conditioning with reference to one example of a learned response.',[
 'Classical conditioning involves learning an association between stimuli. In an illustrative example, an initially neutral sound repeatedly occurs shortly before food that naturally produces salivation. The food is the unconditioned stimulus and salivation to it is the unconditioned response. The sound initially has no such predictive role.',
 'After association, the sound can function as a conditioned stimulus and elicit a conditioned salivary response when food is absent. The learned response need not be identical in every feature to the original response. The explanation concerns a predictive stimulus relationship, rather than a consequence delivered because an individual voluntarily performed a behaviour.'
 ])
add('cog',3,'Limited resources during a task','COG.03','p1-a','general',['perspective','measurement'],
 'Explain cognitive load theory with reference to one example of learning.',[
 'Cognitive load theory considers how limited working-memory resources affect learning and the development of organized knowledge. A novice following a complex assembly instruction may need to coordinate unfamiliar components, terminology and actions at once. If demands exceed available resources, the learner may fail to integrate the instructions meaningfully.',
 'For example, placing explanatory labels beside the relevant components can reduce unnecessary searching between separate pages. The goal is to support learning, rather than remove every intellectual challenge. Existing knowledge changes the demands of a task, so the same instruction can impose different loads on a novice and an experienced learner.'
 ],sources=[SOURCES['load']])
add('cog',4,'A model as an explanatory representation','COG.04','p1-a','general',['perspective','measurement'],
 'Explain how one cognitive model can contribute to understanding behaviour, using an example.',[
 'A cognitive model represents proposed processes and relationships that cannot usually be observed directly. For example, a working-memory model distinguishes processes involved in maintaining verbal and visuospatial information and coordinating attention. This can explain why two concurrent tasks may interfere differently depending on the resources they require.',
 'The model makes predictions that can be compared with behaviour, rather than merely describing an invisible box called thinking. Its components are explanatory constructs, not necessarily separate anatomical containers. A useful example connects a particular prediction to an observable task and recognizes that a successful prediction supports the model without proving that every component is literally represented as drawn.'
 ])
add('cog',5,'Testing a favoured explanation','COG.05','p1-a','general',['bias','causality'],
 'Explain confirmation bias with reference to one example of reasoning.',[
 'Confirmation bias is a tendency to seek, interpret or remember information in ways that favour an existing belief or hypothesis. For example, a person who believes a particular work routine improves concentration may notice successful sessions using it while overlooking equally successful sessions without it or unsuccessful sessions with it.',
 'The mechanism is selective treatment of evidence, rather than simply possessing an opinion. An accurate explanation identifies what evidence would challenge the belief and how it is neglected or reinterpreted. A conclusion can happen to be correct while still having been reached through biased reasoning, so confirmation bias cannot be identified solely from whether the final belief is false.'
 ],sources=[SOURCES['confirmation']])
add('cog',6,'Automatic and deliberate processing','COG.06','p1-a','general',['perspective','change'],
 'Explain dual processing theory with reference to one example of judgement.',[
 'Dual processing theory distinguishes relatively automatic, rapid processing from more deliberate processing that places greater demands on attention and working memory. An experienced reader may recognize a familiar word with little conscious effort but deliberately inspect an unfamiliar word and its sentence before choosing a meaning.',
 'These are functional distinctions, not a claim that two separate people or anatomical brains make decisions. Automatic processing can be accurate and useful, while deliberate thinking can also support a mistaken interpretation. The example should connect task demands and processing characteristics instead of defining the distinction as fast means wrong and slow means correct.'
 ])
add('cog',7,'Consequences and changing behaviour','COG.07','p1-a','general',['change','causality'],
 'Explain the difference between reinforcement and punishment in operant conditioning, using an example of each.',[
 'Operant conditioning concerns how consequences affect the future likelihood of behaviour. Reinforcement increases the behaviour it follows: for example, encouraging feedback contingent on completing a practice task may make completing such tasks more likely. Calling the feedback a reinforcer requires its behavioural effect, rather than assuming every pleasant event necessarily works.',
 'Punishment decreases the behaviour it follows. For example, losing access to a valued game after breaking an agreed rule could reduce future rule-breaking. Positive and negative refer to adding or removing a consequence, not to whether it is morally good or bad. The distinction rests on the direction of behavioural change and the contingency involved.'
 ])
add('cog',8,'Organizing knowledge with schemas','COG.08','p1-a','general',['perspective','change'],
 'Explain schema theory with reference to one example of cognition.',[
 'Schema theory proposes that organized prior knowledge guides how people interpret and remember information. A restaurant schema, for example, contains expectations about ordering, receiving food and paying. It can help a person understand an unfamiliar restaurant quickly without reconstructing the purpose of every action from the beginning.',
 'The same expectations may also lead the person to infer a typical event that did not occur, such as remembering table service in a self-service venue. This illustrates both efficient interpretation and possible reconstructive error. Schemas are flexible knowledge structures rather than fixed records that determine every perception, and unexpected experience can prompt their revision.'
 ])

add('cog',9,'An irrelevant starting estimate','COG.01','p1-b','health-wellbeing',['bias','measurement'],
 'A community centre must estimate the preparation time for a new well-being workshop. Before reviewing the actual tasks, one planner sees a random demonstration number labelled “twelve hours”. The planner keeps using twelve as the starting point despite knowing that the number was unrelated to the workshop. Explain how anchoring bias could affect the estimate and distinguish it from using relevant prior experience.',[
 'The arbitrary duration can become a reference from which the planner adjusts rather than constructing an estimate from the required tasks. Insufficient adjustment could leave the judgement inappropriately close to twelve hours even after the planner recognizes that the number provides no evidence about the workshop.',
 'Knowing that a reference is irrelevant does not necessarily remove its influence. A stronger estimate would connect preparation activities, available staff and relevant experience to the judgement. The scenario does not establish how many hours are actually needed, so the answer should explain the possible reasoning bias rather than declare a particular numerical estimate correct.',
 'Relevant prior experience differs because a comparable workshop may provide justified information about task demands. It can still be overgeneralized, but its evidential value needs evaluation. Anchoring here is the undue persistence of an arbitrary reference, not the claim that every starting estimate or use of experience is irrational.'
 ],fig=card_figure('A workshop estimate',[('Initial exposure','An unrelated twelve-hour example'),('Relevant evidence','Tasks and staffing requirements'),('Judgement','Planner retains the initial reference')]),sources=[SOURCES['anchoring']])
add('cog',10,'A cue in a waiting room','COG.02','p1-b','health-wellbeing',['change','causality'],
 'In a fictional account, a distinctive waiting-room chime was initially unremarkable to an adult. Across several visits, the chime preceded an unpleasant procedure that elicited tension. Later, the adult feels tension on hearing the chime even during a visit without that procedure. Apply classical conditioning to this account. Do not propose a procedure for deliberately distressing participants.',[
 'The unpleasant procedure is the unconditioned stimulus and tension to it is the unconditioned response in this account. The chime begins as a neutral stimulus relative to that response. Repeatedly preceding the procedure can make the chime a predictive cue rather than a biologically necessary cause of tension.',
 'The chime can then function as a conditioned stimulus, with tension in its presence becoming a conditioned response. Its occurrence during a visit without the procedure illustrates responding to a learned predictor when the original eliciting event is absent. The response need not reproduce every feature or intensity of the original tension.',
 'This is an explanation based on a stimulus association, not a claim that tension was rewarded or voluntarily chosen. Other expectations may contribute, so the narrative is compatible with conditioning without proving that conditioning is the only process involved. Responsible discussion should explain the supplied case rather than recommend inducing distress to demonstrate it.'
 ],fig=card_figure('The supplied fictional sequence',[('Earlier visits','Chime precedes unpleasant procedure'),('Initial response','Tension during the procedure'),('Later visit','Chime without the procedure')]))
add('cog',11,'A demanding information leaflet','COG.03','p1-b','health-wellbeing',['perspective','responsibility'],
 'A well-being centre gives newcomers an unfamiliar activity schedule. Instructions on one page refer repeatedly to symbols on a separate page, so readers must switch between them while remembering several steps. A designer proposes placing each explanation beside its symbol. Apply cognitive load theory to explain why this could help, and why the change need not help every reader equally.',[
 'The newcomers must understand unfamiliar steps while maintaining links between symbols and explanations. Switching pages adds a coordination demand that does not itself serve the goal of understanding the schedule. Limited working-memory resources can be occupied by searching and retaining these links rather than organizing the activity information.',
 'Integrating each explanation with its symbol could reduce this avoidable demand and make relevant relationships easier to process. The claim concerns presentation and available resources, not a diagnosis of low intelligence or a preference for a fixed visual learning style. The actual content can still require deliberate thought.',
 'Experienced readers may already know the symbols and sequence, so the original presentation imposes less additional demand on them. Excessive explanation could even become redundant. The theory therefore predicts a conditional benefit depending on knowledge and task demands, rather than guaranteeing that one simplified leaflet is best for every person and purpose.'
 ],fig=card_figure('Two presentation arrangements',[('Current leaflet','Instructions and symbols separated'),('Proposed leaflet','Explanations beside their symbols')]),sources=[SOURCES['load']])
add('cog',12,'A cognitive cycle of worry','COG.04','p1-b','health-wellbeing',['perspective','causality'],
 'An illustrative cognitive model proposes this cycle: interpreting an ambiguous message as threatening directs attention toward possible dangers; noticing those dangers then strengthens the threatening interpretation. Explain how the model could account for persistent worry and identify one limitation of the explanation. The model is supplied for analysis, not as a clinical assessment of a real individual.',[
 'The model identifies a feedback relationship rather than treating each thought as independent. A threatening interpretation changes which information receives attention, and the selected information then appears to confirm that interpretation. Worry can persist even though the original message was ambiguous because the person repeatedly processes evidence through the same cycle.',
 'The explanation generates a specific possibility: changing interpretation or the allocation of attention might disrupt the proposed relationship. However, the diagram alone is not evidence that either process causes the other. The model would need relevant observations and comparisons rather than relying on the intuitive appeal of arrows.',
 'One limitation is that persistent worry may also depend on circumstances, bodily states and prior experiences not represented in the simplified cycle. Real danger should not automatically be dismissed as distorted thinking. The model is useful for representing a possible maintenance process, while its completeness and applicability to an individual remain separate questions.'
 ],fig=card_figure('The supplied cognitive proposal',[('Interpretation','Ambiguous message seems threatening'),('Attention','Possible dangers receive priority'),('Proposed feedback','Noticed dangers strengthen interpretation')]))
add('cog',13,'What a teacher records','COG.05','p1-b','human-development',['bias','responsibility'],
 'A teacher initially believes that a child gives up too easily on puzzles. The teacher records occasions when the child stops but rarely records occasions when the child persists or improves. Apply confirmation bias to explain how the teacher could maintain the initial belief. Explain why the account does not establish the child’s actual developmental capacity.',[
 'The initial belief guides which examples are noticed and retained. Recording stopping behaviour while overlooking persistence creates a selective record that can appear to confirm the belief. The teacher is not simply collecting all relevant observations and then reaching an unfavourable conclusion; the selection itself privileges confirming evidence.',
 'An adequate account identifies the missing comparison: episodes of persistence, the demands of different puzzles and changes over time are relevant to the claim. A child might reasonably stop an unsuitable task, and stopping once does not establish a stable disposition. The biased record conceals these distinctions.',
 'The scenario therefore explains a possible process maintaining the teacher’s judgement, not the child’s true limits. Expectations may also influence opportunities and feedback. Responsibility includes seeking meaningful counterexamples and revising labels when warranted, rather than treating a selective account as evidence that the child cannot develop persistence or benefit from support.'
 ],fig=card_figure('A selective record',[('Initial belief','The child gives up too easily'),('Recorded occasions','Stopping a puzzle'),('Often omitted','Persistence and improvement')]),sources=[SOURCES['confirmation']])
add('cog',14,'A quick choice and a reconsidered choice','COG.06','p1-b','human-development',['change','perspective'],
 'In a fictional school discussion, an adolescent immediately prefers a familiar project design. When asked to consider the project’s unfamiliar constraints, the adolescent deliberately compares alternatives and changes the choice. Apply dual processing theory. Explain why the account does not show that every adolescent’s first choice is wrong.',[
 'Familiarity can support a relatively automatic response that requires little deliberate comparison. Considering new constraints then recruits more attention-demanding processing, allowing the adolescent to represent additional information and compare possibilities. The changed choice is compatible with a shift in the contribution of these processes.',
 'Dual processing is not a developmental rule that adolescents possess only fast processing or that adults always deliberate. The scenario demonstrates one person’s processing under particular task demands. A familiar design might have been suitable, and deliberate analysis could also misinterpret a constraint or rationalize an initial preference.',
 'The defensible explanation relates familiarity, available attention and the relevance of the new information to the judgement. Whether the revised choice is better requires criteria about the project’s goals. Speed and later revision alone do not establish accuracy, developmental immaturity or a universal need to reject first impressions.'
 ])
add('cog',15,'Removing repeated reminders','COG.07','p1-b','human-development',['change','causality'],
 'In a fictional household, a young person dislikes repeated reminders about an agreed voluntary tidying routine. Completing the routine promptly stops the reminders, and prompt completion becomes more frequent. Explain the operant conditioning process illustrated. Distinguish it from punishment without recommending the arrangement as a parenting technique.',[
 'Prompt completion is followed by removal of an experience the young person finds aversive: repeated reminders. Because prompt completion becomes more frequent, the supplied consequence functions as reinforcement. It is negative reinforcement because something is removed, not because the effect is morally negative.',
 'Punishment would reduce the future likelihood of the behaviour it follows. The scenario instead describes an increase in prompt completion, so labelling it punishment merely because reminders are unpleasant confuses the stimulus’s quality with the direction of behavioural change. The relevant contingency is completion followed by cessation of reminders.',
 'The scenario supplies the behavioural pattern needed to classify the process, but does not show that this is the only reason for change or an appropriate household policy. Agreement, autonomy and unintended effects matter. Explaining a learning contingency is different from endorsing every situation in which the contingency could operate.'
 ],fig=card_figure('The supplied consequence pattern',[('Behaviour','Prompt completion of the routine'),('Consequence','Repeated reminders stop'),('Later pattern','Prompt completion becomes more frequent')]))
add('cog',16,'Revising a familiar category','COG.08','p1-b','human-development',['change','perspective'],
 'A child initially expects all library books to tell invented stories. The child interprets a new wildlife book as a story until discussion and further examples show that some library books provide factual explanations. Apply schema theory to explain both the initial interpretation and the later revision. No particular age or developmental stage is specified.',[
 'The child’s existing organized knowledge of library books guides interpretation of the unfamiliar example. Expecting an invented story makes that interpretation readily available, so the child initially fits the wildlife book into the established schema rather than independently determining every feature of its purpose.',
 'Discussion and further examples provide information that does not fit the original expectation. The child can revise the schema to include different purposes, distinguishing factual explanation from invented narrative. This shows that a schema can organize experience while remaining responsive to inconsistent information.',
 'The explanation does not require a fixed developmental stage or imply that the child is incapable of learning until a particular birthday. Nor does it establish a universal sequence for all children. It connects prior knowledge, interpretation and revision to the specific example, while recognizing that educational experience affects which expectations are available.'
 ],fig=card_figure('An expectation and a new example',[('Prior expectation','Library books tell invented stories'),('New experience','A wildlife explanation book'),('Further experience','Discussion and contrasting examples')]))
add('cog',17,'A starting point in a shared decision','COG.01','p1-b','human-relationships',['bias','responsibility'],
 'Two adults are negotiating how to divide the time required for a shared voluntary project. Before listing the tasks, one casually proposes that the other do most of the work. Later revisions remain close to that initial proposal, although neither person has justified it. Apply anchoring bias and explain why disagreement alone would not establish this bias.',[
 'The initial proposal can become the reference around which later negotiation occurs. If revisions remain insufficiently adjusted to the actual tasks and available time, the starting allocation may exert more influence than its evidential basis warrants. A social proposal can therefore serve as an anchor without being a random number.',
 'The relevant question is whether judgement is unduly tied to that starting point. The adults may have legitimate reasons for an unequal division, such as differing skills or availability. Those reasons would need examination before concluding that unequal work or disagreement necessarily reflects a cognitive bias.',
 'Anchoring provides one possible explanation of the persistence of an unjustified allocation, not a judgement about either adult’s motives. Responsibility in applying the concept includes distinguishing unfairness, deliberate bargaining and biased estimation. A reasoned explanation relates the initial reference to later adjustment rather than labelling every difficult negotiation irrational.'
 ],fig=card_figure('The negotiation sequence',[('First proposal','An unequal allocation is suggested'),('Relevant information','Tasks and availability not yet listed'),('Later discussion','Revisions remain near the proposal')]),sources=[SOURCES['anchoring']])
add('cog',18,'A family-call cue and an automatic response','COG.02','p1-b','human-relationships',['change','causality'],
 'In a fictional account, a previously unremarkable family-video-call tone repeatedly precedes a brief, unexpected burst of loud microphone feedback. The feedback elicits an automatic startle response. Later, the tone alone elicits anticipatory tension before any feedback occurs. Apply classical conditioning and distinguish this account from an operant explanation of choosing to mute the call. Do not propose a procedure for deliberately distressing participants.',[
 'The sudden loud feedback is the unconditioned stimulus and its automatic startle effect is the unconditioned response. The family-call tone begins as neutral relative to this response. By repeatedly preceding the feedback, the tone can become a conditioned stimulus that elicits anticipatory tension even when no feedback follows. A conditioned response need not duplicate every feature of the original startle.',
 'An operant explanation would instead examine the consequences of muting behaviour. If muting removes an aversive sound and becomes more frequent, that would illustrate negative reinforcement. This concerns a chosen action and its consequences, whereas the classical account concerns an elicited response to a predictive cue. Both processes could operate without being interchangeable explanations.',
 'The family-call context may consequently acquire an unwelcome emotional meaning even though the tone itself did not initially elicit tension. The supplied narrative supports applying the model, not proving that every reaction during a family interaction is conditioned. Explaining it does not require or justify deliberately exposing participants to distressing noise.'
 ],fig=card_figure('Two processes in a fictional call',[('Initially neutral cue','The family-video-call tone'),('Eliciting event','Unexpected loud microphone feedback'),('Behaviour to distinguish','Choosing to mute the call')]))
add('cog',19,'Several demands during a conversation','COG.03','p1-b','human-relationships',['perspective','responsibility'],
 'During a difficult planning conversation, an adult also monitors several message threads and remembers instructions for an unfamiliar booking system. The adult misses part of the partner’s explanation. Apply cognitive load theory to this situation and explain why the missed explanation does not by itself show a lack of care.',[
 'The person is maintaining and coordinating several kinds of information while attempting to understand the conversation. An unfamiliar booking system can demand conscious processing that an experienced user might perform more easily. Together with monitoring messages, this can leave insufficient working-memory resources for integrating the partner’s explanation.',
 'The theory explains a possible limit on processing at that moment, rather than measuring the person’s affection or stable intelligence. Missing information is compatible with overload, although deliberate inattention or other factors remain possible. The observation alone does not uniquely identify any one explanation.',
 'Reducing competing demands or externalizing booking instructions could make the conversation easier to follow, but effectiveness depends on the actual bottleneck. A responsible application avoids using limited capacity as an automatic excuse for every misunderstanding. It relates the concurrent demands to processing and distinguishes this mechanism from conclusions about the relationship’s quality.'
 ],fig=card_figure('Concurrent demands in the scenario',[('Conversation','Understanding the partner’s explanation'),('Messages','Monitoring several threads'),('Booking system','Maintaining unfamiliar instructions')]),sources=[SOURCES['load']])
add('cog',20,'Where a remembered request can fail','COG.04','p1-b','human-relationships',['measurement','perspective'],
 'A supplied cognitive model distinguishes encoding a request, maintaining it while occupied and retrieving it later. An adult hears a partner’s request while distracted and later forgets it. Explain how the model helps generate alternative explanations, and why forgetting alone cannot reveal which process failed.',[
 'The model separates possible processing problems that can produce a similar final outcome. Distraction may prevent effective encoding, so the request is never represented well enough for later use. Alternatively, it may be encoded but poorly maintained while other demands compete, or available information may not be retrieved at the required time.',
 'These alternatives matter because simply calling the person forgetful does not identify the process. Appropriate additional information about attention, immediate recall or useful retrieval cues could help discriminate possibilities. The model generates questions and predictions rather than directly observing the contents of an invisible memory store.',
 'A forgotten request therefore does not prove a lack of concern or identify one particular memory component. Nor do the model’s labels establish separate anatomical locations. Its value is a clearer set of explanations that can be evaluated against relevant evidence, while recognizing that motivation, communication and relationship context may also influence what happens.'
 ])
add('cog',21,'A rule that is never challenged','COG.05','p1-b','learning-cognition',['bias','causality'],
 'Students propose that every object sorted into a fictional “Luma” category must have a stripe. When allowed to ask about new examples, they choose only striped objects that they already expect to be Luma and overlook opportunities to ask about unstriped examples. Explain how confirmation bias could limit their learning of the category rule.',[
 'The students seek examples likely to fit their preferred explanation rather than testing information that could reveal its inadequacy. If some unstriped objects can also be Luma, examining only apparently confirming examples may leave the overly restrictive rule unchallenged. A sequence of positive cases does not establish that no counterexample exists.',
 'The relevant issue is the diagnostic value of the chosen examples, not a requirement that every question must produce a negative answer. Comparing competing rules can make a carefully selected confirming case informative. Here, however, the students neglect available cases that would distinguish their stripe rule from broader alternatives.',
 'The scenario does not disclose the actual rule, so an answer should not invent it. It explains why the selection strategy can preserve an inadequate hypothesis and restrict learning. Actively considering what would count against a proposed rule is different from simply becoming more confident after collecting examples consistent with it.'
 ],sources=[SOURCES['confirmation']])
add('cog',22,'A familiar answer in a new task','COG.06','p1-b','learning-cognition',['perspective','change'],
 'A learner instantly chooses a familiar procedure for a new task. A prompt then draws attention to a changed constraint, and the learner deliberately checks whether the procedure still applies. Use dual processing theory to explain why the check could improve learning, and why deliberate checking is not guaranteed to produce a correct answer.',[
 'The familiar procedure can be triggered relatively automatically, reducing the effort needed to begin. That efficiency is useful when the new task genuinely matches prior experience. A changed constraint may make the familiar response unsuitable, so deliberate checking allows the learner to represent the difference and evaluate the procedure’s applicability.',
 'The benefit comes from considering relevant information, not from slowness itself. Deliberate processing also depends on knowledge and can be directed toward defending an initial response. A learner who misunderstands the changed constraint might spend more time and still choose an inappropriate procedure.',
 'The theory therefore supports a conditional role for checking when automatic transfer may be misleading. It does not require replacing all fluent expertise with exhaustive deliberation. Explaining how the task differs and how the check uses that distinction connects the processing account to learning more precisely than assuming every first answer must be rejected.'
 ],fig=card_figure('A familiar procedure under review',[('Automatic response','Use a familiar procedure'),('New information','One task constraint has changed'),('Deliberate check','Does the procedure still apply?')]))
add('cog',23,'A consequence that changes participation','COG.07','p1-b','learning-cognition',['change','measurement'],
 'In a fictional learning club, a student earns a token immediately after submitting a short practice explanation. Tokens can be exchanged for a chosen optional club activity. Submitting explanations becomes more frequent. Explain the operant process illustrated and why the tokens’ pleasantness alone would not have been enough to classify it.',[
 'The supplied contingency adds a token after the target behaviour, and the behaviour becomes more frequent. The consequence therefore functions as positive reinforcement in this account. Positive refers to adding something, while reinforcement refers to the increase in future submission of explanations.',
 'A token does not automatically reinforce every student or behaviour simply because the club intends it as a reward. Its function is identified by its effect in the relevant contingency. If submissions did not increase, calling it reinforcement solely because it appeared attractive would confuse an intended reward with a demonstrated behavioural function.',
 'The scenario supports the classification but not the claim that token use improves deep understanding, intrinsic interest or long-term learning. Those are different outcomes. An accurate explanation distinguishes increased submission from educational quality and avoids assuming that an immediate change in participation establishes the best approach to teaching.'
 ])
add('cog',24,'Remembering an unfamiliar exhibition','COG.08','p1-b','learning-cognition',['perspective','measurement'],
 'A learner visits an exhibition arranged unlike a conventional museum. Later, the learner remembers a ticket desk near the entrance, although the exhibition had no ticket desk. The learner often visits ticketed museums. Apply schema theory to explain a possible source of the remembered detail, and identify a limit of that explanation.',[
 'Prior museum experiences can produce an organized expectation about entrances, tickets and display areas. This schema helps interpret the new exhibition, but may also contribute a typical detail when the visit is reconstructed later. The remembered desk could be an inference consistent with prior knowledge rather than a preserved record of the particular event.',
 'The explanation does not imply deliberate dishonesty or that all remembered details are inaccurate. Schemas usually support efficient understanding, and the error concerns a specific plausible addition. Describing the expectation and its possible contribution is more precise than merely stating that memory is unreliable.',
 'The scenario alone does not establish that a schema caused the error. Confusion with another visit, suggestions from another person or ambiguity in the question are possible alternatives. The account is a plausible interpretation that would require appropriate evidence to distinguish it from these explanations, rather than a direct observation of a schema inside the learner’s mind.'
 ],fig=card_figure('Prior knowledge and a particular visit',[('Prior experience','Frequent visits to ticketed museums'),('This exhibition','No ticket desk at the entrance'),('Later recollection','A ticket desk near the entrance')]))

# Conceptual extended responses: the conclusions are qualified worked arguments,
# not mandatory positions or additive fifteen-point marking lists.
add('cog',25,'Confirmation and the evaluation of well-being claims','COG.05','p1-c','health-wellbeing',['bias','responsibility','causality'],
 'Discuss how confirmation bias can affect the responsible evaluation of claims about psychological well-being.',[
 'A claim about psychological well-being may attract support because it fits an existing belief about what makes people feel better. Confirmation bias can influence which accounts are sought, how ambiguous experiences are interpreted and which failures are remembered. A person might collect enthusiastic testimonials for a favoured programme while discounting reports that it did not help.',
 'The causal problem is that apparent improvement can have several explanations. Expectations, changing circumstances or other support may contribute, and selective attention to successes can conceal these possibilities. Responsible evaluation therefore asks whether the evidence distinguishes the proposed explanation from alternatives, rather than treating agreement with a prior belief as a sufficient test.',
 'Bias can also operate against an unfamiliar claim. Someone committed to an established account may examine a new approach only for weaknesses while excusing comparable weaknesses in familiar approaches. Responsibility requires applying relevant standards consistently, not assuming that scepticism is unbiased simply because it produces a negative judgement.',
 'A counterargument is that prior knowledge legitimately guides evaluation: not every proposal deserves equal confidence or unlimited investigation. This is important because abandoning all expectations would be impractical. The distinction is between revisable expectations supported by relevant knowledge and a process that systematically protects a belief from evidence that could count against it.',
 'Confirmation bias therefore presents a significant risk without explaining every disagreement about well-being. A justified conclusion evaluates how evidence was selected, what would change the evaluator’s mind and whether outcomes actually match the claim. Recognizing bias should improve the standards used to assess a claim, rather than become a label used to dismiss whoever disagrees.'
 ],fig=card_figure('An evaluation problem',[('Existing belief','A preferred well-being explanation'),('Available accounts','Benefits, failures and alternatives'),('Judgement','Which accounts receive serious attention?')]),sources=[SOURCES['confirmation']])
add('cog',26,'Is deliberation always better for health judgement?','COG.06','p1-c','health-wellbeing',['perspective','responsibility'],
 'Evaluate the claim that deliberate processing always improves judgements about psychological health and well-being.',[
 'Deliberate processing can improve a judgement when it enables a person to consider relevant alternatives, compare evidence and question an attractive initial impression. For example, a well-being campaign may appear persuasive because its language is familiar. Taking time to inspect what its claims actually mean can reveal unsupported assumptions or outcomes different from those a reader values.',
 'However, the dual processing distinction does not identify accuracy by processing speed. An experienced person may recognize an important pattern efficiently, while extended deliberation can be based on mistaken knowledge. Time spent rehearsing a preferred explanation may strengthen rationalization rather than broaden the range of evidence considered.',
 'The value of deliberation also depends on the decision and available resources. Some judgements allow careful comparison, whereas urgent situations or fatigue constrain it. Requiring exhaustive analysis of every minor choice could itself be burdensome. Responsibility involves deciding when additional checking is likely to provide useful information and when appropriate expert support is needed.',
 'A defence of the claim is that deliberate processing allows errors to be detected that automatic processing may overlook. This is a genuine advantage, but an opportunity is not a guarantee. The process must have access to relevant information, a suitable standard of judgement and enough willingness to revise the first response. Otherwise scrutiny can remain superficial.',
 'The word “always” is therefore unjustified. Deliberation is most useful when a judgement requires comparison that an automatic response does not adequately represent. A stronger conclusion combines efficient processing with targeted review of uncertainty, stakes and evidence. It avoids presenting automatic thought as inherently defective or deliberate thought as a universally reliable route to well-being.'
 ])
add('cog',27,'Rewarding a health-related habit','COG.07','p1-c','health-wellbeing',['change','responsibility','causality'],
 'Examine the value and limitations of operant conditioning for explaining sustained changes in voluntary health-related habits.',[
 'Operant conditioning can explain how consequences alter the likelihood of a habit. An adult who chooses a regular activity may become more likely to repeat it when the activity is followed by a valued social experience or encouraging feedback. The explanatory claim concerns the relationship between behaviour and its consequences, not merely whether someone describes an incentive as pleasant.',
 'This perspective makes useful distinctions between beginning a behaviour, repeating it under a particular contingency and sustaining it after that contingency changes. Increased participation while an external reward is available does not establish persistence after its removal. Understanding the conditions under which the behaviour continues is necessary before claiming a lasting health-related change.',
 'The account also has limits as a complete explanation. Access, personal goals, fatigue and the meaning of the activity affect whether a consequence is available or valued. More frequent performance is not automatically healthier, and a measure of participation should not be substituted for psychological well-being or physical benefit without justification.',
 'A counterargument is that goals and preferences themselves can be shaped by learning history, so an operant explanation can incorporate more than simple prizes. This strengthens its explanatory range, but does not remove the need to specify observable contingencies and distinguish the account from explanations that would predict the same outcome. Broad flexibility must not become an unfalsifiable claim that every change was reinforced.',
 'Operant conditioning is therefore valuable for analysing particular patterns of habit change but insufficient to guarantee sustained beneficial outcomes. Responsible application respects voluntary choice, avoids coercive contingencies and evaluates maintenance alongside relevant outcomes. The best conclusion links specific consequences to a defined behaviour while acknowledging the wider circumstances that enable or constrain change.'
 ])
add('cog',28,'Schemas and the meaning of a symptom report','COG.08','p1-c','health-wellbeing',['measurement','perspective','responsibility'],
 'Discuss how schema theory can inform the interpretation of people’s reports of psychological well-being without dismissing their experiences as unreal.',[
 'Schema theory proposes that prior knowledge organizes attention, interpretation and recall. Expectations about stress or well-being may influence which experiences a person notices and how those experiences are described. For example, someone expecting a difficult transition may interpret a temporary lapse in concentration differently from someone who sees the transition as an opportunity.',
 'This perspective matters for measurement because a report is not a transparent recording of an experience independent of language and prior understanding. Question wording and available categories can interact with schemas. Two people with similar experiences may use different labels, while the same person may describe an earlier experience differently after acquiring a new explanatory framework.',
 'However, interpretation is not equivalent to fabrication. An experience can be distressing and consequential even when its meaning is shaped by expectations. It would be irresponsible to use schema theory as an automatic reason to dismiss reports or assume that correcting a belief will remove every difficulty. Biological conditions and present circumstances may also contribute.',
 'One counterargument is that emphasizing schemas makes reports seem too subjective to be useful. This conclusion is too strong: structured questions, contextual information and converging indicators can improve interpretation. The purpose is to clarify what a measure captures and why reports may differ, rather than replace the person’s account with a supposedly assumption-free judgement.',
 'Schema theory consequently provides a useful partial explanation of how well-being is understood and communicated. A balanced conclusion distinguishes the reality of an experience from the processes used to categorize and recall it. Responsible measurement listens to reports, examines context and treats alternative interpretations as questions to investigate rather than as proof that the experience never occurred.'
 ])
add('cog',29,'An early label as a reference point','COG.01','p1-c','human-development',['bias','measurement','change'],
 'Evaluate the role of anchoring bias in adults’ judgements of a developing child’s abilities.',[
 'Adults often make judgements about developing abilities from incomplete information. An early label or initial performance can become a reference point against which later behaviour is interpreted. If adjustment is insufficient, a child who struggled on an unfamiliar first task may continue to be judged as generally incapable despite later progress or evidence from different tasks.',
 'Anchoring is useful here because it identifies a particular judgement process: undue influence of the initial reference. It is not synonymous with every expectation or all prejudice. An earlier observation may contain relevant information, but its weight should depend on task conditions, subsequent evidence and the developmental change being assessed rather than on its position at the beginning.',
 'Measurement complicates the inference. A difficult first task could reflect language familiarity, instructions, fatigue or limited opportunity rather than the broad ability adults intend to judge. Later assessments may also measure different skills. Claims about insufficient adjustment require a clear account of what has changed and what evidence should reasonably alter the judgement.',
 'A counterargument is that apparent persistence of an initial judgement may reflect stable performance or relevant experience rather than an anchor. This matters because disagreement with an optimistic later interpretation does not itself demonstrate bias. Competing explanations should be considered, including whether adults had access to the same evidence and whether their criteria were appropriate.',
 'Anchoring can therefore help explain some persistent labels but cannot be assumed from a single developmental judgement. A defensible conclusion encourages revisable assessments and attention to new evidence, while distinguishing arbitrary references from justified knowledge. The concept is strongest when it explains how a starting point distorts interpretation, rather than simply criticizing any continuity in adults’ expectations.'
 ],fig=card_figure('A developmental judgement to evaluate',[('Starting reference','An early label or first performance'),('Later information','New tasks, practice and progress'),('Adult judgement','How much is the reference revised?')]),sources=[SOURCES['anchoring']])
add('cog',30,'Learned emotional responses across development','COG.02','p1-c','human-development',['change','causality'],
 'To what extent can classical conditioning explain changes in emotional responses during human development?',[
 'Classical conditioning can explain how a previously neutral cue acquires emotional significance through its relationship with another event. A child may come to anticipate enjoyment at a location repeatedly associated with welcoming activities, or discomfort at a cue associated with an unpleasant experience. The explanation connects changing responses to learning history rather than assuming the response was present from birth.',
 'This account can also explain why responses change when predictive relationships change. Repeated safe experiences with a cue may reduce a conditioned response. However, reduced responding does not necessarily mean the original association has been erased: the context and later experiences may affect whether a response returns. Development should not be represented as a simple permanent deletion of earlier learning.',
 'Causal interpretation nevertheless requires care. Emotional development involves interpretation, observation of others, maturation and changing social conditions. A cue may be meaningful because a child has been told what it signifies, rather than because the child directly experienced repeated pairings. Similar outward responses can therefore arise through different pathways.',
 'A defence of conditioning is that these additional processes can interact with learned associations rather than refute them. This is reasonable, but the account still needs predictions that identify the contribution of a particular association. If every emotional change is retrospectively described as conditioning without specifying relevant stimuli or learning history, the explanation loses precision.',
 'Classical conditioning consequently explains important components of developmental emotional change, especially when a cue’s predictive history is clear. Its reach is partial rather than universal. A stronger conclusion integrates associations with cognitive and social processes, acknowledges context-sensitive change and avoids treating learned responses as either inevitable or permanently fixed after a single experience.'
 ])
add('cog',31,'Instruction for developing learners','COG.03','p1-c','human-development',['perspective','responsibility','change'],
 'Discuss the value and limitations of cognitive load theory when designing instruction for developing learners.',[
 'Cognitive load theory offers a useful perspective on the demands instruction places on limited working-memory resources. A novice who must interpret unfamiliar symbols, remember several steps and search separate explanations may have little capacity left to organize the underlying relationships. Reducing avoidable searching can make the same content more accessible without changing its educational purpose.',
 'Development matters, but chronological age is not the only relevant difference. Prior knowledge can organize information into meaningful units, making a complex task less demanding for an experienced learner. Instruction suitable for one learner may therefore be unnecessarily detailed or insufficiently supported for another learner of a similar age.',
 'Responsibility requires distinguishing supportive design from a fixed judgement of capacity. A learner’s difficulty with one presentation does not prove low intelligence or a permanent limit. Language, accessibility and opportunity also affect demands. The theory should guide revisable decisions about tasks and support rather than justify excluding learners from challenging material.',
 'A counterargument is that reducing demands too far may remove the activity needed to build understanding. This is important: effortless performance during instruction is not identical to lasting learning. Useful design can reduce irrelevant demands while retaining appropriately supported reasoning, and the balance may change as knowledge develops. One universal rule that all difficulty is harmful is not supported.',
 'The theory is therefore valuable for diagnosing and redesigning instructional demands, but limited as a complete developmental or educational account. Its predictions should be evaluated against understanding, retention and transfer, not only immediate ease. A qualified conclusion adapts support to knowledge and goals while remaining open to individual needs and meaningful intellectual challenge.'
 ],sources=[SOURCES['load']])
add('cog',32,'What a developmental cognitive model explains','COG.04','p1-c','human-development',['perspective','measurement','change'],
 'Examine the value and limitations of cognitive models for explaining developmental change. Refer to at least one model or clearly specified example.',[
 'A cognitive model can clarify what is proposed to change as learners develop, instead of using age itself as an explanation. For example, a model may distinguish changes in maintaining information, directing attention and organizing prior knowledge. It can generate different predictions about why a learner succeeds on one task but struggles when several demands must be coordinated.',
 'The value of this approach is explanatory precision. If a child’s improvement is attributed to a particular process, researchers can ask what other tasks should improve and under which conditions. Models also make assumptions visible, allowing alternatives such as continuous improvement and more qualitative reorganization to be compared rather than treated as interchangeable descriptions.',
 'Measurement presents a challenge because task performance can depend on understanding instructions, language and motivation as well as the target process. A model that interprets every failure as absence of an ability may underestimate what a learner can do in a more suitable task. Developmental inferences need to distinguish change in the proposed process from changes in other demands.',
 'A counterargument is that simplification is unavoidable and does not invalidate a model. This is correct: no model can reproduce every feature of development. The relevant test is whether its simplifications support useful, discriminating predictions and acknowledge circumstances where they fail. Adding a new unmeasured component for every unexpected result would weaken rather than improve explanatory value.',
 'Cognitive models consequently provide important tools for understanding developmental change, but their components should remain testable constructs rather than literal containers or universal age labels. A justified conclusion assesses the particular process, evidence and competing explanation. Models are most useful when they explain patterns of change and guide better questions, rather than merely rename an age-related performance difference.'
 ])
add('cog',33,'Confirmation during interpersonal disagreement','COG.05','p1-c','human-relationships',['bias','perspective','responsibility'],
 'Evaluate the claim that confirmation bias is the main cause of persistent interpersonal disagreement.',[
 'Confirmation bias can contribute to persistent disagreement when people selectively notice or interpret evidence supporting an existing view of each other. Someone who expects a partner to be inconsiderate may remember delayed replies while overlooking reliable support. Each new ambiguity can then appear to confirm the established interpretation, making revision less likely.',
 'This mechanism explains persistence more precisely than simply saying that people refuse to agree. It identifies how the available information is treated and suggests that genuinely diagnostic counterexamples may be ignored. The same process can affect both positive and negative expectations; maintaining an unrealistically favourable view can also involve selective interpretation.',
 'However, disagreement may reflect different values, interests, access to information or actual harmful behaviour. These are not automatically cognitive errors. A person may reasonably maintain a judgement because the counterexamples are weak or irrelevant. Treating every justified concern as confirmation bias risks shifting responsibility away from behaviour that needs to be addressed.',
 'A defence of the claim is that even real differences are interpreted through prior expectations, so bias can amplify nearly any conflict. This supports its possible contribution, but does not establish that it is the main cause. Demonstrating primacy requires comparison with other explanations and a clear definition of whether the outcome is disagreement, hostility or failure to resolve a practical problem.',
 'The general claim is therefore too strong. Confirmation bias is a plausible maintenance process in some interpersonal disagreements, but its role depends on the evidence and context. A responsible conclusion examines selective reasoning without using a bias label to dismiss legitimate perspectives, and distinguishes improving the evaluation of evidence from requiring everyone to reach the same judgement.'
 ],fig=card_figure('Illustrative views of one delay',[('Person A’s view','A delay means little concern'),('Person B’s view','A delay reflects competing demands'),('Their discussion','Each recalls different examples')]),sources=[SOURCES['confirmation']])
add('cog',34,'Deliberation during disagreement','COG.06','p1-c','human-relationships',['perspective','change'],
 'Discuss whether deliberate processing is more useful than automatic processing for resolving interpersonal disagreements.',[
 'Deliberate processing can help when an immediate interpretation overlooks another person’s perspective or a relevant constraint. Pausing to distinguish what was said from what was inferred may make alternative explanations available. In a disagreement about a missed commitment, deliberate consideration of circumstances can prevent a familiar negative interpretation from being accepted without inspection.',
 'Automatic processing nevertheless has useful functions. Familiar social skills can enable fluent listening and recognition of emotional cues without consciously rehearsing every step. An experienced person may respond sensitively through well-practised processes. Requiring constant explicit analysis could disrupt an interaction or consume resources needed to attend to the other person.',
 'Nor is deliberate thought necessarily fair. People can use effort to construct arguments defending their own position, repeatedly revisit grievances or interpret ambiguous evidence through an existing belief. More thinking improves resolution only if it is directed toward relevant information and revisable understanding, rather than toward more elaborate rationalization.',
 'A counterargument is that automatic social reactions often reproduce prejudice or habitual hostility, so deliberate checking remains essential. This is persuasive in situations where a habitual response is poorly suited to the evidence or the stakes. It supports targeted review, however, rather than a universal ranking of processing types independent of the task, knowledge and emotional conditions.',
 'Neither type is therefore uniformly more useful. Effective resolution may combine fluent interpersonal skills with deliberate examination of uncertain interpretations and consequences. A qualified judgement defines what resolution means, considers whether the disagreement involves a cognitive misunderstanding or a substantive conflict, and evaluates whether the chosen process actually helps rather than assuming that slower thought is automatically wiser.'
 ])
add('cog',35,'Consequences, cooperation and autonomy','COG.07','p1-c','human-relationships',['causality','responsibility','change'],
 'Examine the value and ethical limitations of explaining cooperation in human relationships through operant conditioning.',[
 'Operant conditioning can explain how responses from others influence future cooperative behaviour. Appreciation following a helpful action may make similar actions more likely, while an aversive consequence may reduce a particular response. The account directs attention to actual contingencies rather than assuming that an intended reward necessarily has its intended effect.',
 'Its value is especially clear when patterns of consequences unintentionally maintain a behaviour. For example, an apparently discouraging reaction may still provide attention that the person values. However, this remains a hypothesis about a specified behavioural pattern, not a reason to assume that every social response is motivated by obtaining rewards.',
 'Cooperation also involves goals, norms, interpretation and mutual commitments. The same response can be understood as appreciation, manipulation or an obligation depending on the relationship. A behavioural description may predict repetition without fully explaining what the action means to the people involved or whether the relationship is fair.',
 'A defence of the operant perspective is that acknowledging these meanings does not remove the influence of consequences. This is reasonable, but explanatory relevance does not justify any intervention designed to control another person. Autonomy, consent, dependence and the possibility of coercion matter, especially when one person controls access to valued resources or social contact.',
 'Operant conditioning is therefore useful as one analysis of how cooperation changes, while limited as a complete account or ethical justification. Responsible use distinguishes understanding a contingency from endorsing manipulation, and evaluates consequences for both parties. A stronger conclusion integrates behavioural effects with the purposes and responsibilities of the relationship rather than reducing cooperation to compliance obtained by incentives.'
 ])
add('cog',36,'Relationship expectations and their revision','COG.08','p1-c','human-relationships',['perspective','change','bias'],
 'Discuss how schemas can both support and obstruct the development of human relationships.',[
 'Schemas organize prior social knowledge and expectations, allowing people to interpret familiar interactions efficiently. Expectations about friendship, for example, can help someone anticipate reciprocity, understand an invitation and coordinate shared activities. Without organized prior knowledge, each social event would require extensive interpretation from the beginning.',
 'The same organization can obstruct a developing relationship when expectations are applied too rigidly. A person may interpret an unfamiliar communication style as disinterest because it does not match a familiar pattern. Recalling schema-consistent episodes more readily can maintain this interpretation even when other interactions suggest a different meaning.',
 'Change is therefore central. New experiences may refine a schema or reveal that different people and situations require different expectations. However, a single contradictory event does not always require abandoning well-supported prior knowledge. The question is whether the schema is being appropriately updated or protected from evidence that should meaningfully challenge it.',
 'A counterargument is that focusing on schemas underestimates differences in actual behaviour and unequal power. Some expectations may be accurate, and harmful treatment should not be reframed automatically as a misunderstanding produced by the recipient’s knowledge structures. A schema explanation needs to distinguish the person’s interpretation from the events and social conditions being interpreted.',
 'Schemas consequently support relationships through efficient understanding while risking bias and rigidity. Their effect depends on fit, flexibility and the quality of new information. A balanced conclusion neither treats expectations as inherently harmful nor presents them as fixed scripts; it examines how people use and revise prior knowledge while acknowledging the reality and responsibilities of their interactions.'
 ])
add('cog',37,'Reference examples and grading judgements','COG.01','p1-c','learning-cognition',['bias','measurement','responsibility'],
 'Examine how anchoring bias can affect judgements of learners’ work, while distinguishing an inappropriate anchor from a legitimate assessment standard.',[
 'A teacher judging unfamiliar work may be influenced by an initial score, a previous learner’s response or an early impression. If later judgement remains unduly close to that reference despite relevant evidence, anchoring can distort the assessment. The concern is not merely variation between scores but an influence unsupported by the criteria used to judge the work.',
 'A legitimate standard serves a different role. A clearly justified example can illustrate what a criterion requires and help assessors interpret it consistently. Its influence is appropriate insofar as the judgement remains tied to the actual features of the learner’s response. The same numerical reference can therefore be useful or misleading depending on its basis and use.',
 'Measurement requires separating target achievement from irrelevant information such as a learner’s earlier reputation. An assessor who begins from a prior score may fail to recognize improvement or a different demand in the present task. In contrast, changing a score merely to move away from the reference would not improve validity if the original score was warranted.',
 'One counterargument is that experienced assessors cannot judge without reference to prior examples. This is correct and shows why eliminating all references is neither possible nor desirable. The stronger aim is to examine whether relevant criteria and evidence govern adjustment, including occasions when the new work meaningfully differs from the reference example.',
 'Anchoring thus presents a plausible threat to fair measurement, but cannot be inferred solely because assessors use standards or produce similar scores. Responsible judgement makes the basis of comparison explicit, tests early impressions against the full response and remains open to justified revision. The concept is most useful when it identifies undue persistence of a reference rather than condemning comparison itself.'
 ],fig=card_figure('Two roles for an initial reference',[('Potential anchor','An unrelated earlier score'),('Legitimate standard','A criterion-linked response example'),('Present evidence','Features of this learner’s work')]),sources=[SOURCES['anchoring']])
add('cog',38,'Classroom emotion is not the whole of learning','COG.02','p1-c','learning-cognition',['causality','change','perspective'],
 'Evaluate the claim that classical conditioning provides a sufficient explanation of emotional responses to learning environments.',[
 'Classical conditioning can explain how a learning environment acquires emotional significance through association. A previously unremarkable room or sound might come to predict supportive activities or unpleasant experiences. Responding to that cue before the next event occurs is consistent with learning a predictive relationship between stimuli.',
 'This explanation has value because emotional responses need not reflect the immediate event alone. An apparently safe task can evoke tension through its connection with earlier experiences. Similarly, familiar contextual cues can support anticipation of enjoyable learning. The account identifies a possible history linking a present response to a cue.',
 'However, students can also respond to meanings acquired through discussion, observation, goals or current treatment. A learner may feel concern because an assessment has real consequences, without needing repeated direct pairings of a neutral cue and an unpleasant event. Different processes can produce similar outward behaviour, so the response itself does not uniquely identify conditioning.',
 'A defence of the claim is that conditioning may contribute alongside these processes and that cognitive expectations can interact with associations. This supports an integrated explanation but undermines sufficiency: if additional processes are required to explain how a cue is interpreted and why its relevance changes, conditioning alone does not provide the entire account. An explanation should state what its own mechanism specifically predicts.',
 'The sufficiency claim is therefore too strong. Classical conditioning offers a useful explanation for some cue-related emotional changes but not every response to a learning environment. A balanced conclusion considers direct experience, interpretation and social conditions, while recognizing that supportive change should not be reduced to deliberately exposing learners to distressing demonstrations of conditioning.'
 ])
add('cog',39,'Should all learning feel easy?','COG.03','p1-c','learning-cognition',['perspective','causality','measurement'],
 'Evaluate the claim that reducing cognitive load as far as possible always improves learning.',[
 'Reducing unnecessary cognitive demands can improve learning when limited working-memory resources are diverted from understanding. For example, searching between separated instructions and symbols can require effort that does not help a novice grasp their relationship. Integrating relevant information can free resources for processing the content that matters.',
 'The claim becomes problematic when every form of effort is treated as harmful. Constructing an explanation or applying knowledge to a new situation may be demanding because it requires the very processing that supports learning. Removing that activity can make immediate performance easier while reducing opportunities to develop understanding or transfer.',
 'Prior knowledge also changes what imposes a demand. Detailed support that helps a novice may be redundant for an experienced learner, while unsupported problem solving may overwhelm someone unfamiliar with the content. Consequently, neither maximum guidance nor minimum guidance is universally appropriate, and the relevant comparison depends on the task and learner.',
 'A defence of load reduction is that complex thinking cannot succeed when available resources are already overwhelmed. This is persuasive, but it supports managing demands rather than minimizing all processing. Appropriate sequencing or external support can preserve meaningful reasoning while reducing irrelevant coordination. Claims about improvement also need an outcome: quick completion, delayed retention and new-task transfer are not interchangeable.',
 'The word “always” is therefore unwarranted. Cognitive load theory is useful for identifying avoidable demands and matching support to knowledge, but ease is not a complete measure of learning. A justified conclusion evaluates which demands are reduced, which learning processes remain and whether the resulting gains extend beyond a smoothly completed practice task.'
 ],sources=[SOURCES['load']])
add('cog',40,'How to judge a memory model','COG.04','p1-c','learning-cognition',['measurement','perspective','causality'],
 'Discuss how psychologists can judge the usefulness of a cognitive model of memory. Refer to at least one model or clearly specified example.',[
 'A useful cognitive model of memory should do more than rename successful and unsuccessful remembering. It should specify proposed processes and generate predictions that can be compared with performance. For example, distinguishing verbal and visuospatial maintenance can predict why certain pairs of concurrent tasks interfere more than others under particular conditions.',
 'Explanatory precision allows comparison with alternatives. If another model explains the same pattern, researchers need observations that distinguish their predictions rather than treating any successful recall as support for every memory theory. A model can be useful for one task while requiring modification or additional processes to explain another.',
 'Measurement is important because memory tasks also require attention, perception, language and strategies. Poor recall does not uniquely identify failure of one proposed component. Converging tasks can strengthen an interpretation, but their demands need examination; a diagram of separate boxes is not itself proof of separate stores or separate anatomical locations.',
 'A counterargument is that a simplified model can remain valuable despite imperfect predictions. This is correct: an accessible representation may guide instruction or help organize research. However, practical convenience should be distinguished from evidence that its mechanisms are accurate. Repeatedly adding unspecified processes after each unexpected outcome can protect a model at the expense of testability.',
 'Usefulness is therefore judged through the clarity and range of predictions, quality of evidence, comparison with alternatives and appropriate applications. A balanced conclusion accepts simplification while requiring explicit limits. The strongest memory model is not necessarily the most detailed diagram, but one that explains relevant patterns and generates informative questions without turning its representational components into unexamined facts.'
 ])

